  Skill_117315_tempBattleDesc_1 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de Daño y obtiene 3 capas de <ZuiyinKeywords:Sello del pecado>. Al jugarla, baraja esta Carta en la parte superior del Mazo de robo. Al jugarla por 3.ª vez, <DepleteIconKeywords:consume> y hace que la siguiente Tarjeta de comando propia disfrute del Efecto de \"Redención de Agonía\" ([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño, gana 3 capas de <ZuiyinKeywords:Sello del pecado>. Después de jugar, baraja esta carta en la parte superior del mazo de robo. En la 3ª jugada, <DepleteIconKeywords:Consumo> y otorga a la siguiente tarjeta de comando el efecto de \"Redención de Agonía\" y se activa 2 veces ([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_3 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de Daño y aplica [Arg3]% Sangrar, obtiene 3 capas de <ZuiyinKeywords:Sello del pecado>. Al jugarla, baraja esta Carta en la parte superior del Mazo de robo. Al jugarla por 3.ª vez, <DepleteIconKeywords:consume> y hace que la siguiente Tarjeta de comando propia disfrute del Efecto de \"Redención de Agonía\" ([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_4 = {
    Text = "Inflige <Damage:[Damage:Arg1]> de Daño, aplica [Arg3]% como Sangrar y gana 3 Acumulaciones de <ZuiyinKeywords:Sello del pecado>. Al jugar, baraja esta carta a la cima del Mazo de robo, establece su Coste de Aritmética en 0 este turno y aplica 100% de Daño <BleedingIconKeywords:Sangrar> al jugarla. En la 3ª vez que se juegue, <DepleteIconKeywords:Agota> y hace que la siguiente Tarjeta de comando disfrute del efecto \"Redención de Agonía\" y surta efecto dos veces ([Arg2]/3)."
  },
  Skill_117315_tempBattleDesc_5 = {
    Text = "Inflige <Damage:[Damage:Arg1]> puntos de daño y aplica [Arg3] % de sangrado, obtiene 3 capas de <ZuiyinKeywords:Marca de Pecado>. Tras jugarla, baraja esta carta en la parte superior del mazo de robo, el coste de poder de cálculo en este turno se convierte en 0 y aplica <BleedingIconKeywords:sangrado> equivalente al 100% del daño. Al jugarla por 3.ª vez, se <DepleteIconKeywords:consume> y la siguiente carta de instrucción propia recibe el efecto \"Redención del Sufrimiento\" y se activa 2 veces([Arg2] /3)."
