  Skill_119763_AwakerSkillBackgroundStory = {
    Text = "Ella es arrogante. Usa su arrogancia para ocultar el vacío irreparable en su interior.\nHa olvidado quién era, ha olvidado quién debería ser.\nMiles de creyentes del marinero se arrodillan ante sus pies, y ella, en medio de los ecos de veneración, ha olvidado lo más importante: \nya se ha sometido a este pálido destino."
  },
  Skill_119763_BattleDesc = {
    Text = "Gana 2 puntos de aritmética, roba 2 cartas. Al comienzo de la próxima ronda, recibe [Arg3] puntos de <SacrificeKeyWord:Ritual de sacrificio>. <RippleKeywords:Réplica>: elimina [Arg4] puntos de <SacrificeKeyWord:Ritual de sacrificio>."
  },
  Skill_119763_Desc = {
    Text = "Obtén 2 puntos de aritmética, roba 2 cartas. Al comenzar el próximo turno, recibe un <SacrificeKeyWord:Ritual de sacrificio> del [Arg1]% de la vida máxima. <RippleKeywords:Réplica>: elimina un <SacrificeKeyWord:Ritual de sacrificio> del [Float:Arg2]%."
  },
  Skill_119763_EffectNameList = {
    Text = "Eliminar Proporción de Sacrificio"
  },
  Skill_119763_Name = {
    Text = "Canto del abismo"
  },
  Skill_119764_AwakerSkillBackgroundStory = {
    Text = "La procedencia de la estatua de marfil que sostiene Murphy es objeto de diversas opiniones. \n Algunos dicen que la estatua proviene de un sitio sumergido en el Aequor, explorado bajo la dirección de Murphy, mientras que otros afirman que la estatua nació junto con el corazón que late en su pecho, el Niño Santo. \n Pero lo que es indudable es que esta estatua, que simboliza los múltiples lazos entre ella y la ciudad de Schraubverschwinden, silenciosa en el fondo del mar desconocido, apareció en la vista de los Marchadores de mares el día en que Murphy se convirtió en la \"verdadera Madre divina\". \n Desde entonces, los fieles también han testificado cómo Murphy utilizó esta estatua de marfil para abrirse camino a través de las tormentas y cortar el mar de sangre. \n El poder absoluto, a menudo, no se limita a ser un símbolo ilusorio. La rodilla de la humanidad solo se arrodillará ante la autoridad de la fuerza absoluta."
  },
  Skill_119764_BattleDesc = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo, al comienzo del siguiente turno recibe [Arg7] puntos de <SacrificeKeyWord:ritual de sacrificio>. Aplica [Arg3] capas <DwmofeiKeywords:ritual de nacimiento> a todos los enemigos, inflige [Arg4] veces <Damage:[Damage:Arg5]> puntos de daño al enemigo con más vida, disfrutando de un [Arg6]% de bonificación en <TentacleInjurieIconKeywords:daño de tentáculo>."
  },
  Skill_119764_Desc = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de blindaje, al comienzo del próximo turno, recibe [Arg2]% de <SacrificeKeyWord:ritual de sacrificio> de tu vida máxima. Aplica [Arg3] capas de <DwmofeiKeywords:ritual de nacimiento> a todos los enemigos, inflige [Arg4] veces <Damage:[Damage:Arg5]> puntos de daño al enemigo con más vida, disfrutando de un [Arg6]% de bonificación en <TentacleInjurieIconKeywords:daño de tentáculos>."
  },
  Skill_119764_EffectNameList = {
    Text = "Blindaje, capas de ritual de nacimiento, Daño, bonificación de daño de tentáculos"
  },
  Skill_119764_Name = {
    Text = "Princesa ilusoria"
  },
  Skill_119764_OverLimitUtlSkillDesc = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo, al inicio del siguiente turno recibirás [Arg7] puntos <SacrificeKeyWord:ritual de sacrificio>. Aplica [Arg8] capas <DwmofeiKeywords:ritual de nacimiento> a todos los enemigos, inflige [Arg4] veces <Damage:[Damage:Arg5]> puntos de daño al enemigo con más PV, disfrutando de un [Arg6]% de bonificación en <TentacleInjurieIconKeywords:daño de tentáculo>. Coloca en tu mano 3 cartas de coste de aritmética 2 de\"Danza Circular de Luo Yan\"y dales <DepleteIconKeywords:consumo> y <PrepareKeypvewords1:preparar1>."
  },
  Skill_119764_PropertyNameList = {
    Text = "Defensa *GrowValue1,$GrowValue2,Ataque *GrowValue3,$GrowValue4％"
  },
  Skill_119765_AwakerSkillBackgroundStory = {
    Text = "Ella es frívola. Usa la ligereza para luchar contra la realidad destrozada.\nBailemos, dijo, un baile dedicado a lo divino.\nAgradece a los dioses por concedernos una causalidad perversa, un pasado desordenado y un futuro esquivo.\nBajo el foco, ella es el único centro de toda existencia."
  },
  Skill_119765_BattleDesc = {
    Text = "Obtén <Posse:[Arg7]> puntos de Llave Plateada. Según la postura de tentáculo, obtén diferentes efectos: \"Mareas crecientes\": <TentacleInjurieIconKeywords:daño de tentáculos> +[TentaclePower:Arg1], genera 1 tentáculo. \"Mar tranquilo\": obtén <Block:[Block:Arg2]> puntos de blindaje, el blindaje se retiene al 50% hasta el siguiente turno. \"Olas furiosas\": causa [Arg3] veces <Damage:[Damage:Arg4]> puntos de daño al enemigo con más PV, disfrutando de un [Arg5]% de bonificación en <TentacleInjurieIconKeywords:daño de tentáculo>."
  },
  Skill_119765_Desc = {
    Text = "Obtén [Arg6]% de regeneración de llave plateada. Según la postura de tentáculo obtendrás diferentes efectos: \"Mareas crecientes\": <TentacleInjurieIconKeywords:daño de tentáculos> +[TentaclePower:Arg8], genera 1 tentáculo. \"Mar tranquilo\": obtén <Block:[Block:Arg9]> puntos de escudo, el escudo se mantiene al 50% hasta el siguiente turno. \"Olas furiosas\": causa [Arg3] veces <Damage:[Damage:Arg4]> puntos de daño al enemigo con más vida, disfrutando de un [Arg5]% de bonificación en <TentacleInjurieIconKeywords:daño de tentáculo>."
  },
  Skill_119765_EffectNameList = {
    Text = "Daño de tentáculos, blindaje, daño, bonificación de daño de tentáculos, eficiencia de regeneración de Llave Plateada"
  },
  Skill_119765_Name = {
    Text = "Danza Circular de Luo Yan"
  },
  Skill_119765_PropertyNameList = {
    Text = "Poder de ataque*GrowValue1,Defensa*GrowValue2,Poder de ataque*GrowValue3,$GrowValue4％,$GrowValue5％"
  },
  Skill_119766_AwakerSkillBackgroundStory = {
    Text = "Ella goteó la sangre del cordón umbilical de Dios en el mar. Ella ora a Dios por un camino que nunca alcanzará su destino.\n Mientras las burbujas de sueños persistan, ella es la única Madre divina."
  },
  Skill_119766_Desc_0 = {
    Text = "Murphy: Falso Engendro obtiene <Energy:[Energy:Arg1]> puntos de alienación. <ExaltIconKeywords:Activar>: el daño causado por Murphy: Falso Engendro añade un [Arg2]% de <SacrificeKeyWord:Ritual de sacrificio>. Al comienzo del turno, gana 1 capa de <MingqiKeywords:Pacto del destino>."
