  Skill_122485_AwakerSkillBackgroundStory = {
    Text = "No olvides el pasado, no olvides al Grupo de investigación del Reino de la Niebla.\nOlvidar significa traicionar.\nY ella, Mouchette, nunca traicionará."
  },
  Skill_122485_Desc_0 = {
    Text = "Mouchette obtiene <Energy:[Energy:Arg1]> Alienación. <ExaltIconKeywords:Despertar>: Las instancias de Daño de \"Encuentro dramático\" +2. Cada vez que se activa \"Encuentro dramático\", el Daño Final Temporal de \"golpear\" de Mouchette +25%. Genera inmediatamente 1 \"Explosión humana\" Temporal."
  },
  Skill_122485_Desc_15 = {
    Text = "Mouchette obtiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Activar>: Las instancias de Daño de \"Encuentro dramático\" +2. El límite de activaciones por turno se aumenta a 5. Cada vez que se activa \"Encuentro dramático\", el Daño Final Temporal de \"golpear\" de Mouchette +25%. Genera inmediatamente 2 \"Explosión humana\" Temporales con 0 de Coste de Aritmética."
