  },
  Skill_125371_AwakerSkillBackgroundStory = {
    Text = "Ellos nunca hablan de su origen, solo de la inmensa alegría indescriptible que acompañó su nacimiento.\nTu conciencia se derretirá en la euforia, tu pasado se derretirá en la euforia, tu cráneo se derretirá en la euforia... tu materia gris se derretirá en la euforia.\nSolo disfruta de los suaves y tiernos bocadillos—con \"anhelo\" como atracción."
  },
  Skill_125371_BattleDesc_0 = {
    Text = "Inflige <Damage:[Damage:Arg1]> puntos de Daño crítico garantizado a todos los enemigos y activa [Arg2]% de Veneno. <ResonanceKeywords:Resonancia 3>: <EmbryoFusionIconKeywords:Fusión Embrionaria> +[Arg4]( [Arg5]/3 )."
  },
  Skill_125371_BattleDesc_1 = {
