  },
  Skill_126490_AwakerSkillBackgroundStory = {
    Text = "Cuando el telón se alzó, los títeres levantaron la cabeza y contemplaron el rostro apacible detrás de la rueca.\nLos hilos se tensaron, y entre las canciones y danzas de los títeres, ella sonrió como lo haría una madre. En el teatro del destino, ella era su única audiencia."
  },
  Skill_126490_BattleDesc_0 = {
    Text = "Aracne obtiene <Energy:[Energy:Arg1]> puntos de Aliemus. <ExaltIconKeywords:Despertar>: \"Aniquilación\" se convierte en: elegir 1 Tarjeta de comando del Espacio Hiperspacial, retírala y haz que se active dos veces la próxima vez que se juegue, haciendo que la siguiente Tarjeta de comando jugada active <SingularityKeywords3:Lanzadera Dimensional>."
  },
  Skill_126490_BattleDesc_15 = {
    Text = "Arachne obtiene <Energy:[Energy:Arg1]> Alienación. <ExaltIconKeywords:Despertar>: \"Aniquilación\" cambia a: \"Saca una Tarjeta de comando elegida del Espacio Hiperspacial y llévala a la mano; se activa +1 vez al jugarse. Por cada enemigo, inflige <RealDamage:Daño Fijo> igual al 50% de su <CutKeywords:Veredicto Final>. El Escudo del personaje y la Amplificación de Daño obtenidos del próximo Exaltar de Arachne +50%. La próxima Tarjeta de comando jugada activa <SingularityKeywords3:Lanzadera Dimensional>.\""
  },
  Skill_126490_Desc_0 = {
