  Skill_130928_Name_1 = {
    Text = "¡Abismo! ¡Vórtice! ¡Gran Bomba"
  },
  Skill_130929_AwakerSkillBackgroundStory = {
    Text = "¡Agita el aterrador cañón con alegría y salta al campo de batalla!\nNo importa la preocupación, no importa el peligro, porque todo esto es tan insignificante en comparación con los amigos.\n\"¡Amigo, problemas! ¡Mosk, entra en acción!\""
  },
  Skill_130929_BattleDesc_0 = {
    Text = "Mosk obtiene <Energy:[Energy:Arg1]> puntos de alienación. <ExaltIconKeywords:Activar>: roba 1 carta de\"¡Cargar!\". Después de que Mosk libere Perseguir, la próxima explosión de alienación de Mosk disfrutará de una bonificación de daño de tentáculos adicional del [Arg2]%, acumulándose hasta un máximo de [Arg3] veces."
  },
  Skill_130929_BattleDesc_15 = {
    Text = "Mosk obtiene <Energy:[Energy:Arg1]> Alienación. <ExaltIconKeywords:Despertar>: Roba 1 \"¡Cargar\". Después de que Mosk desencadene Caza, su próximo Exaltar obtiene una Bonificación de daño de tentáculos adicional del [Arg2]%, y el próximo Exaltar inflige <RealDamage:Daño Fijo> igual al [Arg4]% del PV Max al enemigo con más PV, acumulándose hasta [Arg3] <plural value=\"[Arg3]\" singular=\"vez\" plural=\"veces\">."
  },
  Skill_130929_Desc_0 = {
    Text = "Mosk obtiene [Arg5]% Aliemus Base. <ExaltIconKeywords:Despertar>: Roba 1 \"¡Cargar\". Después de que Mosk Libere una Buscar, la siguiente Exaltar Alienación de Mosk obtiene adicionalmente [Arg2]% Bonificación de daño de tentáculos, acumulable hasta [Arg3] veces."
  },
  Skill_130929_Desc_15 = {
    Text = "Mosk obtiene Alienación igual al [Arg5]% de su Alienación básica. <ExaltIconKeywords:Despertar>: Roba 1 \"¡Cargar\". Después de que Mosk desencadene Caza, su próximo Exaltar obtiene una Bonificación de daño de tentáculos adicional del [Arg2]%, y el próximo Exaltar inflige <RealDamage:Daño Fijo> igual al [Arg4]% del PV Max al enemigo con más PV, acumulándose hasta [Arg3] <plural value=\"[Arg3]\" singular=\"vez\" plural=\"veces\">."
  },
  Skill_130929_EffectNameList = {
