  Skill_131115_Name = {Text = "Lex Volis"},
  Skill_131192_Desc = {
    Text = "Reduce el Coste de Aritmética en 1 de todas las cartas con <ErosionColorInkKeywords:Distorsión de Percepción> en la mano, por cada una otorga <Energy:5> puntos de Alienación al Cuerpo Despertado con menor Alienación, luego restaura todas las cartas con <ErosionColorInkKeywords:Distorsión de Percepción> en cualquier posición. Después de Jugar una carta este turno, ya no aplica <ErosionColorInkKeywords:Distorsión de Percepción> a otras cartas."
  },
  Skill_131192_Name = {
