  Skill_131241_Desc = {
    Text = "El jugador obtiene [Power:Arg1] puntos de <PowerIconKeywords:fuerza>, <Block:[Block:Arg2]> puntos de blindaje, [Heal:Arg3] puntos de curación, [TentaclePower:Arg4] puntos de <TentacleInjurieIconKeywords:daño de tentáculos>, [Counterattack:Arg5] capas <RetaliateIconKeywords:contrataque>, inflige <Damage:[Damage:Arg6]> puntos de daño a los enemigos de la fila frontal [Arg7] veces, aplica [Poison:Arg8] capas <IntoxicationIconKeywords:veneno>, y aplica [Exhaustion:Arg9] capas <ExhaustionIconKeywords:absorber>."
  },
  Skill_131241_Name = {
