  Skill_131856_AwakerSkillBackgroundStory = {
    Text = "Ojos, oídos, lengua, piel, cerebro: sensaciones que se extienden por todo el cuerpo.\nEl amor y la ternura compartidos te rodearán para siempre, hasta la muerte—"
  },
  Skill_131856_BattleDesc_0 = {
    Text = "Saya obtiene <Energy:[Energy:Arg1]> puntos de Aliemus. <ExaltIconKeywords:Activar>: Tras usar \"Horno Carmesí\", añade <ErosionColorInkKeywords:Distorsión de Percepción> a las Tarjetas de comando de otros Cuerpos Despertados en cada posición que no tengan \"<DestructionKeywords:Destruir>\". Las primeras 3 veces por turno que se Juegue una Tarjeta de comando con <ErosionColorInkKeywords:Distorsión de Percepción>, Saya y el Cuerpo Despertado al que pertenece dicha Tarjeta de comando obtienen <Energy:[Energy:Arg2]> puntos de Aliemus."
  },
  Skill_131856_BattleDesc_15 = {
    Text = "Saya obtiene <Energy:[Energy:Arg1]> puntos de Alienación. <ExaltIconKeywords:Activar>: Después de usar \"Horno Carmesí\", Saya obtiene <Energy:[Energy:Arg4]> puntos de Alienación y 1 capa de \"<KaiHuajishu:Gynoecium>\". Añade <ErosionColorInkKeywords:Distorsión de Percepción> a las Tarjetas de comando de otros Cuerpos Despertados en cualquier posición que no tengan \"<DestructionKeywords:Destruir>\". Las primeras 3 veces por turno que se juegue una Tarjeta de comando con <ErosionColorInkKeywords:Distorsión de Percepción>, Saya y el Cuerpo Despertado al que pertenece dicha Tarjeta de comando obtienen <Energy:[Energy:Arg2]> puntos de Alienación."
  },
  Skill_131856_Desc_0 = {
    Text = "Saya obtiene [Arg3] % de Aliemus Base. <ExaltIconKeywords:Activar>: Tras usar \"Horno Carmesí\", aplica <DestructionKeywords:Distorsión de Percepción> a las tarjetas de comando de otros Despertados que no posean \"<ErosionColorInkKeywords:Destruir>\". Las primeras 3 veces por turno que se juega una tarjeta de comando con <ErosionColorInkKeywords:Distorsión de Percepción>, Saya y el Despertado al que pertenece la tarjeta obtienen <Energy:[Energy:Arg2]> puntos de Alienación."
  },
  Skill_131856_Desc_15 = {
    Text = "Saya obtiene [Arg3]% de Aliemus Base. <ExaltIconKeywords:Activar>: Tras usar «Horno Carmesí», Saya obtiene <Energy:[Energy:Arg4]> puntos de Alienación y 1 capa de «<KaiHuajishu:Gynoecium>». Aplica <ErosionColorInkKeywords:Distorsión de Percepción> a las tarjetas de comando de otros Despertados que no posean «<DestructionKeywords:Destruir>». Las primeras 3 veces por turno que se juega una tarjeta de comando con <ErosionColorInkKeywords:Distorsión de Percepción>, Saya y el Despertado al que pertenece la tarjeta obtienen <Energy:[Energy:Arg2]> puntos de Alienación."
  },
