  Skill_131858_AwakerSkillBackgroundStory = {
    Text = "Aterrador, hermoso, desesperado; bajo la corrupción del \"Amor\", esa vida resplandeciente canta en plena floración.\nEsta es la canción que anuncia el inicio de un nuevo mundo y la caída del antiguo."
  },
  Skill_131858_BattleDesc = {
    Text = "[<DevouredIconKeywords:Devorar>: El coste de Aritmética de 2 tarjetas de comando básicas copiadas aleatorias de \"Golpe Básico\" o \"Defensa básica\" se convierte en 0 y tiene efecto 1 vez adicional.] Obtén <Block:[Block:Arg1]> puntos de Blindaje. Elige otro Cuerpo Despertado, genera 1 Copia Básica de cada una de todas sus tarjetas de comando básicas y colócalas respectivamente en el Mazo de robo y en el Mazo de Descarte, con <NothingnessIconKeywords:Oblivion> y <DestructionKeywords:Destruir> adjuntos. Consume todos los <KaiHuajishu:Gynoecium>; por cada capa consumida, el coste de Aritmética de 1 tarjeta de [habilidad] aleatoria entre ellas se convierte en 0."
  },
  Skill_131858_Desc = {
