  Skill_132429_AwakerSkillBackgroundStory = {
    Text = "El océano es profundo y silencioso, lleva el anhelo por la vida y el miedo a la muerte. \n Pero hay quienes insisten en llenar el mar con risas y juegos—cuando Aurita hace tal invitación, siempre surge la sensación de \"¿por qué no acompañarla en esta diversión?\", dejando que la simple alegría llene el pecho."
  },
  Skill_132429_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño. Consume hasta 10 cartas de \"División de glándulas\" del mazo de robo y del mazo de descarte, causando 1 daño adicional por cada carta. Añade 2 cartas de \"División de glándulas\" a tu mano. Aumenta el daño que \"Aurita\" causará en esta batalla en [Arg2] puntos."
  },
  Skill_132429_Desc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de <PunctureDamagewords:daño de perforación>. Consume hasta 10 cartas de \"División de glándulas\" del mazo de robo y del mazo de descarte, infligiendo 1 daño adicional por cada carta. Añade 2 cartas de \"División de glándulas\" a tu mano. Aumenta el daño que \"Aurita\" inflige en esta batalla en [Arg2] puntos."
  },
