  Skill_132432_AwakerSkillBackgroundStory = {
    Text = "Los niños poco a poco verán la esencia de los cuentos de hadas y entenderán las fábulas detrás de los mitos. En el lenguaje humano, este proceso se llama \"crecer\".\n Pero también hay niños que creerán cada vez más en las historias de antes de dormir, convencidos de que realmente hay un puente arcoíris en el cielo y que hay civilizaciones hundidas en el fondo del mar.\n A Aurita le gustan estas historias, y quiere compartir esta alegría con más amigos."
  },
  Skill_132432_Desc_0 = {
    Text = "<TentacleInjurieIconKeywords:daño de tentáculo> +[TentaclePower:Arg1]. Descarta todas las cartas en tu mano y roba la misma cantidad de cartas. Baraja 1 carta \"División de glándulas\" en el montón de descarte."
  },
  Skill_132432_Desc_1 = {
    Text = "<TentacleInjurieIconKeywords:daño de tentáculo> +[TentaclePower:Arg1]. Descarta todas las cartas en tu mano y roba la misma cantidad +1. Baraja 1 carta de \"División de glándulas\" en el montón de descarte."
  },
