  Skill_132433_AwakerSkillBackgroundStory = {
    Text = "Existe una medusa especial en el mundo que, al ser herida, puede regenerar su tejido y convertirse de nuevo en un hidra completa.\n\"¡Aurita también produce medusas! Entonces, ¡aurita también es medusa!\"\nEn esta etapa de percepción infantil del mundo, mejor no arruinar su entusiasmo"
  },
  Skill_132433_Desc_0 = {
