  Skill_132435_AwakerSkillBackgroundStory = {
    Text = "La niña se fue con pesar del acuario en quiebra; como pago por su trabajo, se le permitió llevarse a casa unas cuantas medusas. \n Estas son sus pequeñas criaturas favoritas, espíritus flotantes del mar ilusorio, flores de vida eterna. \n ¡Con tal de cuidarlas con esmero, llenarían todo el tanque! — Ella había esperado ver tal escena."
  },
  Skill_132435_Desc_0 = {
    Text = "Aurita obtiene <Energy:[Energy:Arg1]> puntos de alienación. <ExaltIconKeywords:Activar>: Obtiene 1 tentáculo, pon 2 cartas de \"División de glándulas\" en la mano. Cuando Aurita causa daño, [Arg2] tentáculos atacan 1 vez."
  },
  Skill_132435_Desc_15 = {
    Text = "Aurita obtiene <Energy:[Energy:Arg1]> puntos de locura. <ExaltIconKeywords:Despertar>: obtiene 1 tentáculo y añade 2 cartas de \"División de glándulas\" a tu mano. Cuando Aurita causa daño, haz que [Arg2] tentáculos ataquen 1 vez. El \"golpear\" de Aurita se convierte en daño penetrante y causa 2 puntos de daño adicionales."
  },
