  Skill_133322_Desc_1 = {
    Text = "Inflige <Damage:[Damage:Arg1]> de daño al enemigo en la primera fila y obtiene <Energy:[Energy:Arg2]> de locura"
  },
  Skill_133322_Name_1 = {Text = "golpear"},
  Skill_133323_BattleDesc_1 = {
    Text = "Inflige <Damage:[Damage:Arg4]> de daño al enemigo de la fila delantera. Por cada [Arg2] de vida perdida, daño +[Arg3]. Se recupera la misma cantidad de vida."
  },
  Skill_133323_Desc_1 = {
    Text = "Inflige <Damage:[Damage:Arg1]> de Daño al enemigo de la fila delantera. Por cada [Arg2] PV perdidos, Daño +[Arg3], y restaura una cantidad igual de PV."
  },
  Skill_133323_Name_1 = {Text = "Saquear"},
  Skill_133324_Desc_1 = {
    Text = "Inflige <Damage:[Damage:Arg1]> de Daño a todos los enemigos y aplica <PVPCognitiveDissonanceKeyWords:Distorsión de Percepción>."
  },
  Skill_133324_Name_1 = {
    Text = "Canción de Saya"
  },
  Skill_133325_BattleDesc_1 = {
    Text = "Selecciona un aliado, le otorga <Heal:[Heal:Arg4]> <PVPFeatheredSeedsKeyWords:Gynoecium> y la misma cantidad de PV; por cada [Arg2] de Aritmética consumida, <PVPFeatheredSeedsKeyWords:Gynoecium> y la misma cantidad de PV aumentan [Arg3]."
  },
  Skill_133325_Desc_1 = {
    Text = "Elige un aliado para que obtenga <Heal:[Heal:Arg1]> de <PVPFeatheredSeedsKeyWords:Gynoecium> y una cantidad igual de PV. Por cada [Arg2] de Aritmética gastada, el <PVPFeatheredSeedsKeyWords:Gynoecium> y los PV equivalentes aumentan en [Arg3]."
  },
  Skill_133325_Name_1 = {
    Text = "Propagación"
  },
  Skill_133346_Desc_1 = {
    Text = "Inflige <PVPSeriousInjuryKeywords:Plaga>, <PVPPenetrateKeywords:Atravesar>, <DelayKeywords:Latencia>: Recupera <Heal:[Heal:Arg1]> PV a todos los aliados. Por cada [Arg2] Blindaje dispersado por <PVPSeriousInjuryKeywords:Plaga> o curado por <DelayKeywords:Latencia>, la Recuperación de PV +[Arg3]."
  },
  Skill_133346_Name_1 = {
    Text = "Dedicado al nuevo mundo"
  },
  Skill_133346_UnknownName = {
    Text = "Dedicado al nuevo mundo"
  },
  Skill_133347_Desc_1 = {
    Text = "<PVPWeaponKeywords:Rueda del destino>: Se conserva tras la muerte de esta Rueda del destino. Cuando el Portador muere y al final de los siguientes [Arg2] turnos en Estado de muerte, los demás aliados obtienen <Heal:[Heal:Arg1]> de <PVPFeatheredSeedsKeyWords:Gynoecium> y PV."
  },
  Skill_133347_Name_1 = {
    Text = "Que el mundo se convierta en fragancia"
  },
  Skill_133348_Desc_1 = {
    Text = "<PVPWeaponKeywords:Rueda del destino>: Después de equipar, las descripciones de \"golpear\", \"Habilidad\" y \"Exaltar\" del Portador se vuelven no identificables, pero cada instancia de Daño, Escudo del personaje y Cicatrización se incrementa aleatoriamente en [Arg1]%~[Arg2]%."
  },
  Skill_133348_Name_1 = {
    Text = "Cuento de hadas en el barro"
  },
  Skill_133365_AwakerSkillBackgroundStory = {
    Text = "Ella había escuchado innumerables veces el sonido de los hilos al romperse.\nUn reencuentro que nunca ocurrió. Una confesión que nunca fue dicha. Un niño que nunca nació.\nUna melodía que nunca vio la luz. Una guerra que nunca fue ganada. Una civilización que nunca sobrevivió.\nLos hilos tejen. Los hilos se rompen. Los hilos vuelven a confluir en aquella inmensa red.\nLa divinidad del destino ya lo sabía desde siempre: nada desaparece realmente, nada ha existido realmente."
  },
  Skill_133365_Desc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de blindaje. Otros Cuerpo Despertados obtienen <Energy:[Energy:Arg2]> puntos de Aliemus. La próxima vez que \"Telar Eterno\" se active, generará un \"<DerivativeCardKeywords_138:Hilos Guía>\" adicional que se coloca en el Mazo de robo y en el Mazo de Descarte."
  },
  Skill_133365_EffectNameList = {
    Text = "Escudo, locura"
  },
  Skill_133365_Name = {
    Text = "Red de ataduras de vida"
  },
  Skill_133365_PropertyNameList = {
