  Skill_142695_AwakerSkillBackgroundStory = {
    Text = "Preservó las partes más vívidas y entrañables de todos sus seres queridos, y otorgó a todos sus enemigos el tormento más atroz y prolongado.\nCada noche de brindis y festejo, caía entre risas en un océano formado por cáscaras vacías."
  },
  Skill_142695_BattleDesc = {
    Text = "Elimina el Estado <ExhaustionIconKeywords:STR▼> propio. Reduce temporalmente [Exhaustion:Arg1] puntos de <ExhaustionIconKeywords:Fortaleza> a todos los enemigos. Inflige <RealDamage:Daño Fijo>( [Arg3] ) equivalente al [Arg2]% del Daño de tentáculos al enemigo con menos PV; si lo Mata, genera 1 carta permanente de \"Gaunt\" <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> y la coloca en tu mano. Se pueden generar como máximo 3 cartas permanentes de \"Gaunt\" por batalla."
  },
  Skill_142695_Desc = {
    Text = "Elimina el estado <ExhaustionIconKeywords:STR▼> propio. El <ExhaustionIconKeywords:STR> de todos los enemigos –[Exhaustion:Arg8] temporalmente. Inflige <RealDamage:Daño Fijo> igual al [Arg2]% del Daño de tentáculos al enemigo con menos PV. Si esto elimina al objetivo, genera 1 \"Gaunt\" permanente<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> en la mano. Máximo 3 \"Gaunts\" permanentes generados por batalla."
