  Skill_142700_AwakerSkillBackgroundStory = {
    Text = "\"¿Qué deseas?\"\nFortaleza, orden, recuperar lo perdido, lavar la sangre con sangre...\nCayó en un largo y sombrío silencio, aunque en realidad ya tenía una respuesta desde hacía tiempo, una respuesta sin solución.\nQuería que el Sol saliera por el este y se pusiera por el oeste, quería que todo siguiera como de costumbre."
  },
  Skill_142700_BattleDesc_0 = {
    Text = "Pontos obtiene <Energy:[Energy:Arg1]> puntos de Alienación. <ExaltIconKeywords:Activar>: Por cada 3 cartas de \"Gaunt\" en el mazo, \"Cacería Implacable\" obtiene 1 capa adicional de <BattueKeywords:Cacería en Manada>. Por cada Carta de Pontos jugada, el efecto de reducción de STR temporal de la próxima \"Cacería Implacable\" aumenta un [Arg3]%, activable hasta 3 veces por turno."
  },
  Skill_142700_BattleDesc_15 = {
    Text = "Pontos obtiene <Energy:[Energy:Arg1]> de Alienación. <ExaltIconKeywords:Despertar>: Por cada 2 \"Gaunts\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> en el mazo, \"Cacería Implacable\" gana 1 acumulación adicional de <BattueKeywords:Cacería en Manada>. Por cada 1 Carta de Pontos jugada, el efecto STR temporal▼ de la siguiente \"Cacería Implacable\" +[Arg3]%, lo cual se activa hasta 3 veces por turno. Obtén +<Energy:[Energy:Arg4]> de Alienación en la 1.ª vez que se juega \"golpear\" y \"Defensa\" cada turno."
  },
  Skill_142700_Desc_0 = {
    Text = "Pontos obtiene [Arg2]% de Aliemus Base. <ExaltIconKeywords:Activar>: Por cada 3 cartas de \"Gaunt\" en el mazo, \"Cacería Implacable\" obtiene 1 capa de <BattueKeywords:Cacería en Manada>. Por cada Carta de Pontos jugada, el efecto de reducción de STR temporal de la próxima \"Cacería Implacable\" aumenta un [Arg3]%, activable hasta 3 veces por turno."
  },
  Skill_142700_Desc_15 = {
    Text = "Pontos obtiene [Arg2]% de Aliemus Base. <ExaltIconKeywords:Despertar>: Por cada 2 \"Gaunts\"<DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> en el mazo, \"Cacería Implacable\" gana 1 acumulación de <BattueKeywords:Cacería en Manada>. Por cada 1 Carta de Pontos jugada, el efecto STR temporal▼ de la siguiente \"Cacería Implacable\" +[Arg3]%, lo cual se activa hasta 3 veces por turno. Obtén +<Energy:[Energy:Arg4]> de Alienación en la 1.ª vez que se juega \"golpear\" y \"Defensa\" cada turno."
  },
