  Skill_142846_AwakerSkillBackgroundStory = {
    Text = "Ni el oído humano ni la Tecnología de núcleo de plata existente pueden extraer por ahora ninguna información útil del silbato de caza de Pontos.\nSin embargo, todos los individuos asimilados por Ebwynnos parecen adaptarse muy rápidamente a seguir las instrucciones de El Silbato."
  },
  Skill_142846_Desc = {
    Text = "Si se libera por primera vez en esta batalla, genera 3 tipos diferentes de \"Gaunt\" <DerivativeCardKeywords_145:><DerivativeCardKeywords_146:><DerivativeCardKeywords_147:> y los coloca en tu mano, obteniendo <Block:[Block:Arg1]> puntos de Blindaje; por cada 4 cartas permanentes de Gaunt que poseas, 1 de ellas se Mejora a \"Gaunts Conjuntos\". De lo contrario, roba 3 cartas de \"Gaunt\"."
  },
