  Skill_144438_Desc_1 = {
    Text = "<PVPWeaponKeywords:Rueda del destino>: Cuando un aliado muere, gana <Energy:[Energy:Arg1]> Alienación. Cuando un aliado es Reanimado, gana <Energy:[Energy:Arg2]> Alienación. El efecto de ganancia de Alienación solo surte efecto cuando la Alienación del objetivo no está llena, hasta [Arg8] veces. Tras agotar el contador, Destruye esta Rueda del destino."
  },
  Skill_144438_Name_1 = {
    Text = "Sincronización de Almas"
  },
  Skill_144486_AwakerSkillBackgroundStory = {
    Text = "El hada y el mago se cruzaron en un desolado rincón de tierra en las afueras de un pequeño pueblo.\nElla sonreía y hacía señas a unos niños extranjeros bien vestidos, mientras el mago tenía los ojos fijos en el tintineo dorado de la pulsera en la muñeca de la madre.\nSus miradas se encontraron en el aire y, en un instante, cada uno comprendió las intenciones del otro.\nEn ese silencioso duelo, el mago demostró ser el más hábil, logrando una ajustada victoria gracias a su dilatada experiencia.\nY así, una nueva y hermosa empresa de engaños y estafas alzó su telón."
  },
  Skill_144486_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Obtén 1 acumulación de <WormGrowth1:Saciedad>. Al infligir DMG, aplica [<Corrosion:Corrosión>:Arg10] acumulaciones de <Corrosion:Corrosión> al objetivo.] Disipa <BurningKeywords2:Quemadura> de todas las cartas en mano. Obtén <Block:[Block:Arg2]> de Escudo del personaje. Inflige <Damage:[Damage:Arg1]> de DMG [Arg8] veces a todos los enemigos. Cada acumulación de <WormGrowth1:Saciedad> aumenta el Daño básico de Exaltar y la Generación de Escudo en [Arg6]%. Consume todas las acumulaciones de <SacrificialMark1:Ofrenda>; cada acumulación aumenta el número de golpes de Exaltar en 1 y se convierte en un número igual de acumulaciones de <WormGrowth1:Saciedad>. Acumulaciones actuales de <WormGrowth1:Saciedad>: [Arg9]. Acumulaciones obtenidas en esta batalla: [Arg11]"
  },
  Skill_144486_BattleDesc_3 = {
    Text = "[<DevouredIconKeywords:Devorar>: Obtén <WormGrowth2:Saciedad>. Al infligir DMG, aplica [<Corrosion:Corrosión>:Arg10] acumulaciones de <Corrosion:Corrosión> al objetivo.] Disipa <BurningKeywords2:Quemadura> de todas las cartas en mano. Obtén <Block:[Block:Arg2]> de Escudo del personaje. Inflige <Damage:[Damage:Arg1]> de DMG [Arg8] veces a todos los enemigos. Cada acumulación de <WormGrowth2:Saciedad> aumenta el Daño básico de Exaltar y la Generación de Escudo en [Arg6]%. Consume todas las acumulaciones de <SacrificialMark1:Ofrenda>; cada acumulación aumenta el número de golpes de Exaltar en 1 y se convierte en un número igual de acumulaciones de <WormGrowth2:Saciedad>. Acumulaciones actuales de <WormGrowth2:Saciedad>: [Arg9]. Acumulaciones obtenidas en esta batalla: [Arg11]"
  },
