  Skill_144486_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Devorar>: Obtén <WormGrowth2:Saciedad>. Al infligir DMG, aplica [<Corrosion:Corrosión>:Arg10] acumulaciones de <Corrosion:Corrosión> al objetivo.] Disipa <BurningKeywords2:Quemadura> de todas las cartas en mano. Obtén <Block:[Block:Arg2]> de Escudo del personaje. La Tasa de Crítico de este Exaltar +50%. Inflige <Damage:[Damage:Arg1]> de DMG [Arg8] veces a todos los enemigos. Cada acumulación de <WormGrowth2:Saciedad> aumenta el Daño básico de Exaltar y la Generación de Escudo en [Arg6]%. Consume todas las acumulaciones de <SacrificialMark1:Ofrenda>; cada acumulación aumenta el número de golpes de Exaltar en 1 y se convierte en un número igual de acumulaciones de <WormGrowth2:Saciedad>. <FaxianKeywords:<FaxianKeywords:Descubre>> 2 conjuntos de cartas de <DerivativeCardKeywords_152:\"Bendición\"> con diferentes <Blessing:Dones>, cada conjunto contiene 3 cartas. Elige 1 conjunto para añadir a tu mano. Reduce permanentemente el <ExhaustionIconKeywords:STR> de todos los enemigos en [Agotamiento:Arg12]. Acumulaciones actuales de <WormGrowth2:Saciedad>: [Arg9]. Acumulaciones obtenidas en esta batalla: [Arg11]"
  },
  Skill_144486_PropertyNameList = {
    Text = "DEF *GrowValue1,ATQ *GrowValue2,ATQ *GrowValue3"
  },
  Skill_144487_AwakerSkillBackgroundStory = {
    Text = "En cada noche despejada en que la nieve estaba a punto de caer, Caraboo trepaba junto a la chimenea y contemplaba en silencio el cielo tenue. Apuntando su varita hacia los cielos, trazaba un conjuro de su propia invención. Y entonces la nieve en polvo a la deriva la llevaba de regreso a aquella noche nevada en que una vez había entregado su alma."
  },
