  Skill_144491_AwakerSkillBackgroundStory = {
    Text = "La codicia es el verdadero color de la naturaleza humana.\nNadie puede resistir la tentación del azúcar, ni siquiera el Hada Madrina en persona.\nCaraboo sonrió de oreja a oreja, dejando al descubierto una boca llena de dientes negros y afilados."
  },
  Skill_144491_BattleDesc_0 = {
    Text = "Caraboo obtiene <Energy:[Energy:Arg1]> de Alienación. <ExaltIconKeywords:Despertar>: Tras usar \"Horno Carmesí\", la siguiente <DerivativeCardKeywords_160:\"Bendición Milagrosa\"> cuesta -3 de Aritmética, y cada opción de <FaxianKeywords:descubrimiento> se mejora a un conjunto que contiene 1 carta de <DerivativeCardKeywords_152:\"Bendición\"> adicional. Elige 1 conjunto para mezclar en tu Mazo de robo."
  },
  Skill_144491_BattleDesc_15 = {
    Text = "Caraboo obtiene <Energy:[Energy:Arg1]> de Alienación. <ExaltIconKeywords:Despertar>: Tras usar \"Horno Carmesí\", la siguiente <DerivativeCardKeywords_160:\"Bendición Milagrosa\"> cuesta -3 de Aritmética, y cada opción de <FaxianKeywords:descubrimiento> se mejora a un conjunto que contiene 2 cartas de <DerivativeCardKeywords_152:\"Bendición\"> adicionales. Elige 1 conjunto para mezclar en tu Mazo de robo. Tras jugar una carta de \"Bendición\", Fusión Embrionaria +10. Este efecto de fusión aumenta según tus Puntos de vida perdidos, hasta un +100%."
  },
  Skill_144491_Desc_0 = {
    Text = "Caraboo obtiene [Arg2]% de Alienación básica. <ExaltIconKeywords:Despertar>: Tras usar \"Horno Carmesí\", la siguiente <DerivativeCardKeywords_160:\"Bendición Milagrosa\"> cuesta -3 de Aritmética, y cada opción de <FaxianKeywords:descubrimiento> se mejora a un conjunto que contiene 1 carta de <DerivativeCardKeywords_152:\"Bendición\"> adicional. Elige 1 conjunto para mezclar en tu Mazo de robo."
  },
  Skill_144491_Desc_15 = {
    Text = "Caraboo obtiene [Arg2]% de Alienación básica. <ExaltIconKeywords:Despertar>: Tras usar \"Horno Carmesí\", la siguiente <DerivativeCardKeywords_160:\"Bendición Milagrosa\"> cuesta -3 de Aritmética, y cada opción de <FaxianKeywords:descubrimiento> se mejora a un conjunto que contiene 2 cartas de <DerivativeCardKeywords_152:\"Bendición\"> adicionales. Elige 1 conjunto para mezclar en tu Mazo de robo. Tras jugar una carta de <Blessing:Bendición>, Fusión Embrionaria +10. Este efecto de fusión aumenta según tus Puntos de vida perdidos, hasta un +100%."
  },
