  Skill_145675_AwakerSkillBackgroundStory = {
    Text = "En realidad, Ogier ya había olvidado el verdadero aspecto de aquel castillo.\nPero ahora, podía erigir nuevas murallas apoyándose en los deseos que guardaba en su corazón.\nSi bajo su protección aún podía escuchar las risas y la alegría de la gente, y las flores familiares volvían a florecer por los campos...\nEntonces, ese corazón que ya había mutado por completo, aún tendría un motivo para permanecer en este mundo."
  },
  Skill_145675_BattleDesc_0 = {
    Text = "Obtiene <Block:[Block:Arg1]> puntos de Blindaje, obtiene [Power:Arg2] puntos de <PowerIconKeywords:Fuerza>, consume toda la <KuangNu:Corriente Oscura>, por cada capa consumida el Blindaje y la Fuerza infligidos aumentan un 33%, obtiene 1 capa de <ShuZui:Autoculpa>."
