  Skill_145676_AwakerSkillBackgroundStory = {
    Text = "En el momento en que cada caballero prestaba juramento al ser investido, el arma que portaba quedaba igualmente bañada en gloria.\nPero aquella primera lanza de plata que le pertenecía, dotada de una sagrada misión, ya se había disuelto entre las brasas de la guerra.\nSin embargo, puesto que ya era un cuerpo cargado de culpa, bien podía convertir esa oscura podredumbre del pecado en una nueva arma. Pensó que así, aunque manchara sus manos con más sangre, ya no deshonraría a sus seres queridos."
  },
  Skill_145676_BattleDesc_0 = {
