  Skill_145677_AwakerSkillBackgroundStory = {
    Text = "Hubo un tiempo en que el joven intentó arrancar de sí mismo aquel maligno lodo negro, pero sin importar lo que hiciera —desgarrarlo con las manos, cortarlo con objetos afilados, golpearlo con objetos contundentes...— la pesadilla invisible nunca desaparecía, sino que se volvía cada vez más insolente.\nAl final, tuvo que admitir que él y Él ya se habían fusionado en uno por completo, sin distinción alguna entre ambos.\nÉl se había convertido en su sombra."
  },
  Skill_145677_BattleDesc_0 = {
    Text = "Quebrantajuramentos·Ogier obtiene <Energy:[Energy:Arg1]> de Alienación. <ExaltIconKeywords:Despertar>: La primera vez que Quebrantajuramentos·Ogier inflige daño con \"Punta de Lanza Manchada de Pecado\" en cada ronda, aplica igual cantidad de <Corrosion:Corrosión>. El Aumento de Escudo de \"Defensa\" aumenta un 50%, roba 1 carta."
  },
  Skill_145677_BattleDesc_15 = {
    Text = "Quebrantajuramentos·Ogier obtiene <Energy:[Energy:Arg1]> de Alienación. <ExaltIconKeywords:Despertar>: La primera vez que Quebrantajuramentos·Ogier inflige daño con \"Punta de Lanza Manchada de Pecado\" en cada ronda, aplica igual cantidad de <Corrosion:Corrosión>. El Daño básico de \"Punta de Lanza Manchada de Pecado\" aumenta un 100%, y además se beneficia de un 200% de bonificación de Poder. El Aumento de Escudo de \"Defensa\" aumenta un 100%, roba 1 carta."
  },
  Skill_145677_Desc_0 = {
    Text = "Quebrantajuramentos·Ogier obtiene [Arg2]% de Alienación básica. <ExaltIconKeywords:Despertar>: La primera vez que Quebrantajuramentos·Ogier inflige daño con \"Punta de Lanza Manchada de Pecado\" en cada ronda, aplica igual cantidad de <Corrosion:Corrosión>. El Aumento de Escudo de \"Defensa\" aumenta un 50%, roba 1 carta."
