  },
  Skill_146016_AwakerSkillBackgroundStory = {
    Text = "La Deidad desgarró su alma y su carne, creyendo que ese era el Juicio definitivo sobre el Caos.\nPero el alma vacía nunca dejó de buscar, y la Fortaleza arrebatada nunca se disipó del todo.\nCuando la armadura de hueso volvió a cubrir su cuerpo, cuando el pulso de Leviatán resonó de nuevo con su voluntad — todas las Ataduras se hicieron añicos en ese instante.\nEl alma y la carne se fusionaron de nuevo en las profundidades del océano estelar. La Bestia del Caos ya no estaba incompleta.\nEste océano estelar volverá a recibir a la versión completa de ella."
  },
  Skill_146016_BattleDesc_0 = {
    Text = "Lotan: Cetarconte obtiene <Energy:[Energy:Arg1]> de Aliemus Base. <ExaltIconKeywords:Despertar>: Las Tarjetas de comando de Lotan: Cetarconte infligen +1 instancia de Daño.\nAl inicio del turno, si <DerivativeCardKeywords_153:\"Mandoble·Caída de Ballena\"> está en la mano: \nEl primer <DerivativeCardKeywords_154:\"Duelo Mortal\"> jugado ese turno potencia tu próxima \"Espada Cortafronteras\"—por cada 1 de Alienación que robe, \"Espada Cortafronteras\" inflige +1% de Daño Final (máx. 90%)."
  },
  Skill_146016_BattleDesc_15 = {
    Text = "Lotan: Cetarconte obtiene <Energy:[Energy:Arg1]> de Aliemus Base. <ExaltIconKeywords:Despertar>: Las Tarjetas de comando de Lotan: Cetarconte infligen +1 instancia de Daño.\nLotan: Cetarconte recibe +50% de Alienación a través de <DerivativeCardKeywords_154:\"Duelo Mortal\">. Al inicio del turno, si <DerivativeCardKeywords_153:\"Mandoble·Caída de Ballena\"> está en la mano: \nEl primer <DerivativeCardKeywords_154:\"Duelo Mortal\"> jugado ese turno potencia tu próxima \"Espada Cortafronteras\"—por cada 1 de Alienación que robe, \"Espada Cortafronteras\" inflige +1,5% de Daño Final (máx. 135%)."
  },
  Skill_146016_Desc_0 = {
    Text = "Lotan: Cetarconte obtiene [Arg2]% de Aliemus Base. <ExaltIconKeywords:Despertar>: Las Tarjetas de comando de Lotan: Cetarconte infligen +1 instancia de Daño.\nAl inicio del turno, si <DerivativeCardKeywords_153:\"Mandoble·Caída de Ballena\"> está en la mano: \nEl primer <DerivativeCardKeywords_154:\"Duelo Mortal\"> jugado ese turno potencia tu próxima \"Espada Cortafronteras\"—por cada 1 de Alienación que robe, \"Espada Cortafronteras\" inflige +1% de Daño Final (máx. 90%)."
  },
  Skill_146016_Desc_15 = {
    Text = "Lotan: Cetarconte obtiene [Arg2]% de Aliemus Base. <ExaltIconKeywords:Despertar>: Las Tarjetas de comando de Lotan: Cetarconte infligen +1 instancia de Daño.\nLotan: Cetarconte recibe +50% de Alienación a través de <DerivativeCardKeywords_154:\"Duelo Mortal\">. Al inicio del turno, si <DerivativeCardKeywords_153:\"Mandoble·Caída de Ballena\"> está en la mano: \nEl primer <DerivativeCardKeywords_154:\"Duelo Mortal\"> jugado ese turno potencia tu próxima \"Espada Cortafronteras\"—por cada 1 de Alienación que robe, \"Espada Cortafronteras\" inflige +1,5% de Daño Final (máx. 135%)."
