  Skill_21615_AwakerSkillBackgroundStory = {
    Text = "Los recuerdos de Ogier están fragmentados debido al fenómeno de erosión.\n Recuerda las risas en el baile, pero ha olvidado el nombre del protagonista del baile; recuerda que fue entrenado en la orden de caballeros, pero no sabe por qué el duque lo convirtió en caballero siendo tan joven; recuerda haber sido aplastado por los caballos de hierro, pero no puede recordar qué tipo de sonrisa estaba protegiendo.\n Nadie puede culparlo, ha cumplido con todas las responsabilidades que un caballero debe asumir, incluso sacrificando su vida por la voluntad de proteger."
  },
  Skill_21615_Desc_0 = {
    Text = "Disipa <FragileIconKeywords:fragilidad>. Obtén <Block:[Block:Arg1]> de escudo y [Power:Arg2] de <PowerIconKeywords:fuerza> temporal"
  },
  Skill_21615_Desc_2 = {
    Text = "Si tienes estado de <FragileIconKeywords:fragilidad>, disípalo y gana <Block:[Block:Arg3]> de escudo. Gana <Block:[Block:Arg1]> de escudo y [Power:Arg2] puntos de <PowerIconKeywords:fuerza> temporal"
  },
  Skill_21615_EffectNameList_0 = {
    Text = "Escudo, fuerza"
  },
  Skill_21615_EffectNameList_2 = {
