  },
  Skill_21615_Name = {
    Text = "Siete Artes y Virtudes"
  },
  Skill_21615_OverLimitUtlSkillDesc_0 = {
    Text = "Disipa el Estado <FragileIconKeywords:Frágil> propio. Obtén <Block:[Block:Arg1]> puntos de Blindaje. Obtén [Power:Arg2] puntos de <PowerIconKeywords:Fortaleza> Temporal. El Blindaje obtenido aumenta un 200%. El número de veces que Ogier inflige Daño +1, durante 3 turnos."
  },
  Skill_21615_OverLimitUtlSkillDesc_2 = {
    Text = "Si tienes estado de <FragileIconKeywords:Frágil>, disípalo y gana <Block:[Block:Arg3]> puntos de escudo. Obtén <Block:[Block:Arg1]> puntos de escudo. Obtén [Power:Arg2] puntos de <PowerIconKeywords:Fortaleza> en este turno. El escudo obtenido aumenta en un 200%. El daño causado por el Ogier aumenta en 1, y dura 3 turnos."
  },
