  Skill_3977_AwakerSkillBackgroundStory = {
    Text = "\"Acércate, no seas tímido, deja que el Sr. Sombrero pruebe tu risa y felicidad.\"\nLa maestra Casiah asiente con la visera del sombrero y, con un estallido, hace aparecer un gran manojo de cintas y cartas. \n\"Elige tu carta en tu corazón. ¡Shh! No se lo digas a nadie. La maestra Casiah te dirá cuál es tu única.\""
  },
  Skill_3977_Desc_0 = {
    Text = "Considerado como un \"golpe\". Elige cualquier 1 carta de <DimensionalSpaceIconKeywords:Ultra Space> para colocar en la mano y reduce su costo aritmético en -2. Causa aleatoriamente <Damage:[Damage:Arg1]> puntos de daño [Arg2] veces, gana [Power:Arg3] puntos de <PowerIconKeywords:Strength> temporal."
