  Skill_3981_AwakerSkillBackgroundStory = {
    Text = "Línea de sangre heredada de otras razas, considerada como herejía. \n Solo creyendo en su nobleza y su grandeza, se puede sobrevivir en este mundo cruel. \n El manuscrito dejado por el tío Ornn, junto con la magnífica ciudad antigua del Aequor que describe, es su único refugio espiritual. \n \"En el momento de la explosión de la sangre, seguramente se otorgará el supremo poder del Aequor, ¿verdad?\""
  },
  Skill_3981_Desc = {
    Text = "Recupera <Heal:[Heal:Arg3]> puntos de vida y disipa <WeaknessIconKeywords:Síntoma: Debilidad> de uno mismo, aplica [Arg4] <plural value=\"[Arg4]\" singular=\"capa\" plural=\"capas\"> de <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos. <TentacleInjurieIconKeywords:Daño de tentáculos> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Contrataque> +[Counterattack:Arg2]. Antes de que comience el próximo turno, por cada Ataque recibido, haz que 1 Tentáculo contraataque."
  },
  Skill_3981_EffectNameList = {
    Text = "Restablece, daño de tentáculo, mostrador"
  },
  Skill_3981_Name = {
    Text = "Linaje de la Herejía"
  },
  Skill_3981_OverLimitUtlSkillDesc = {
    Text = "Recupera <Heal:[Heal:Arg3]> puntos de PV y disipa el Estado <WeaknessIconKeywords:Debilidad> propio, aplica [Arg4] capas de <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos. <TentacleInjurieIconKeywords:Daño de tentáculos> +[TentaclePower:Arg1]. <RetaliateIconKeywords:Contrataque> +[Counterattack:Arg2]. Antes de que comience el próximo turno, por cada Ataque recibido, 1 tentáculo contraataca al atacante. Hace que 1 tentáculo Ataque 5 veces, obteniendo un Contrataque del 25% del Daño infligido."
  },
