  },
  Skill_4018_AwakerSkillBackgroundStory = {
    Text = "Dolor, dolor.\nEl dolor negro y frío es una de las pocas cosas que recuerda.\nSi tuviera una concha dura y bonita como los verdaderos nautilos, ¿no dolería tanto?"
  },
  Skill_4018_Desc_0 = {
    Text = "Nautila obtiene <Energy:[Energy:Arg1]> puntos de aliemus. <ExaltIconKeywords: Despertar> : El escudo que aplica Nautila y <RetaliateIconKeywords: Contraataque> incrementa [Arg2]%"
  },
  Skill_4018_Desc_15 = {
    Text = "Nautila obtiene <Energy:[Energy:Arg1]> de Aliemus. <ExaltIconKeywords:Activar>: Escudo del personaje y <RetaliateIconKeywords:Contador> aplicados por Nautila +[Arg2]%, y el <RetaliateIconKeywords:Contador> Fijo infligido por todos los Cuerpos Despertados +[Arg3]%."
