  Skill_4018_Name = {
    Text = "Experto en mantenimiento"
  },
  Skill_4019_AwakerSkillBackgroundStory = {
    Text = "Como la teoría de uno que da vida a todo y todo regresa a uno, ella cayó en la trampa de la paradoja"
  },
  Skill_4019_Desc_0 = {
    Text = "Obtén <Posse:[Arg1]> puntos de llave plateada. Coloca en tu mano las 3 copias originales de diferentes cartas de comando no derivadas que se jugaron al final del turno anterior, reduciendo su coste de aritmética en 1 y obteniendo <DepleteIconKeywords:consumo> y <NothingnessIconKeywords:ilusión>. Si no hay suficientes cartas de comando para colocar en tu mano, roba cartas en la misma cantidad como sustituto."
  },
  Skill_4019_Desc_3 = {
    Text = "Obtén <Posse:[Arg1]> puntos de energía-s llave de plata. Coloca en tu mano las 3 copias originales de diferentes cartas de comando no derivadas que se jugaron al final del turno anterior, reduciendo su coste de aritmética en 1 y obteniendo <DepleteIconKeywords:consumo> y <NothingnessIconKeywords:ilusión>. Si no hay suficientes cartas de comando para colocar en tu mano, roba cartas en la misma cantidad como sustituto. Elige 1 llave desbloqueada cualquiera para reemplazar la llave actual, usa la llave o recupérala al final del combate."
  },
  Skill_4019_EffectNameList = {
    Text = "Regeneración de Llave Plateada"
  },
  Skill_4019_Name = {
    Text = "Paradoja convergente"
  },
  Skill_4019_OverLimitUtlSkillDesc_0 = {
    Text = "Obtén <Posse:[Arg1]> puntos de Llave Plateada. Coloca en tu Mano una Copia Básica de las últimas 3 Tarjetas de Comando Innatas diferentes jugadas el turno anterior, haciendo que su Coste de Aritmética sea 0 y otorgándoles <DepleteIconKeywords:Consumo> y <NothingnessIconKeywords:Oblivion>. Si no hay suficientes Tarjetas de Comando para colocar en la Mano, roba la misma cantidad en su lugar. Obtén 3 acumulaciones de <TimeBeacon2:Negentropía> sin límite máximo."
  },
  Skill_4019_OverLimitUtlSkillDesc_3 = {
    Text = "Obtén <Posse:[Arg1]> puntos de energía-s llave de plata. Coloca en tu mano las 3 copias originales de diferentes cartas de comando no derivadas que se jugaron al final del turno anterior, haciendo que su coste de aritmética sea 0 y obteniendo <DepleteIconKeywords:consumo> y <NothingnessIconKeywords:ilusión>. Si no hay suficientes cartas de comando para colocar en tu mano, roba cartas en la misma cantidad como sustituto. Elige 1 llave desbloqueada al azar para reemplazar la llave actual, usa la llave o recupérala después de que la batalla termine. Obtén 3 capas de <TimeBeacon2:Negentropía> que ignoran el límite."
  },
