  Skill_4055_AwakerSkillBackgroundStory = {
    Text = "En medio del vasto océano, el barco solitario se mece con las olas. \n Ellos suplican, imploran y ruegan, esperando que la diosa blanca los lleve lejos del mar y los regrese a la tierra de su hogar. \n En el mástil central, la chica de vestido blanco levanta la cabeza y ve un pájaro blanco. \n \"Dame el timón y los llevaré a casa.\""
  },
  Skill_4055_BattleDesc_0 = {
    Text = "Dispersar el estado <HeavyInjuryKeywords:grave> y recuperar <Heal:[Heal:Arg1]> puntos de vida y ganar 1 aritmética. Resucitar al recibir daño letal en esta batalla y recuperar [Arg2]%(<Heal:[Arg3]>) de vida, solo se puede activar 1 vez por batalla"
  },
  Skill_4055_BattleDesc_3 = {
    Text = "Dispersar el estado <HeavyInjuryKeywords:grave>, recuperar <Heal:[Heal:Arg1]> puntos de vida y ganar 1 aritmética. Al recibir daño letal en esta batalla, renacer, recuperar [Arg2]%(<Heal:[Arg3]>) de vida y hacer que todos los Despertados obtengan <Energy:[Energy:Arg4]> puntos de locura. Después de activarse, se necesita un intervalo de 6 turnos para volver a aplicar el efecto de renacimiento."
  },
  Skill_4055_Desc_0 = {
