  Skill_4064_Name = {Text = "Sangrar"},
  Skill_4065_AwakerSkillBackgroundStory = {
    Text = "La malicia superior se agita sin cesar, pero la voluntad humana no está completamente indefensa.\n El líquido negro que disuelve todo debilita su mente, convirtiéndose en la única ayuda de la humanidad.\n El fabricante de marionetas ocupa brevemente la delantera, abre los brazos y transforma la corriente destructiva en un arco protector."
  },
  Skill_4065_BattleDesc_0 = {
    Text = "Obtén [Arg1] puntos temporales de <AlertIconKeywords:alerta>. Obtén <Posse:[Arg2]> puntos de llave plateada. Disipa el estado de <FragileIconKeywords:frágil>. Cada vez que una carta entra en el <DimensionalSpaceIconKeywords:espacio hiperspacial>, transfórmala en <DerivativeCardKeywords_13:\"Liberar: Mecha\">."
  },
  Skill_4065_BattleDesc_1 = {
    Text = "Obtén [Arg1] puntos temporales de <AlertIconKeywords:alerta>. Obtén <Posse:[Arg2]> puntos de llave plateada. Disipa tu estado de <FragileIconKeywords:frágil>. Coloca en tu mano 1 carta de \"DEF\" de Erica con <DepleteIconKeywords:consumo>. Cada vez que una carta entra en el <DimensionalSpaceIconKeywords:espacio hiperspacial>, transfórmala en <DerivativeCardKeywords_13:\"Desatar: Mecha\">."
  },
  Skill_4065_Desc_0 = {
    Text = "Obtén [Arg1] puntos temporales de <AlertIconKeywords:alerta>. Obtén una cantidad equivalente de energía de llave plateada de la regeneración de llave plateada de Erica. Disipa el estado de <FragileIconKeywords:frágil>. Cada vez que una carta entra en el <DimensionalSpaceIconKeywords:espacio hiperspacial>, transfórmala en <DerivativeCardKeywords_13:\"Desatar: Mecha\">."
  },
  Skill_4065_Desc_1 = {
