  },
  Skill_4074_Name = {Text = "Esconder"},
  Skill_4075_AwakerSkillBackgroundStory = {
    Text = "A Nymphaea le gustan mucho las flores; además de las novelas literarias, esta es la única compañía que tiene a su lado en la cama de enferma.\n Sin embargo, desde la muerte de sus padres, nadie le ha traído regularmente un ramo de consuelo.\n Ese último ramo de lirios también ha perdido su frescura con el paso del tiempo.\n Por lo tanto, en su propio funeral, no dudó en llevarlo consigo.\n Los peces nadan al ritmo de las luces y sombras, los corales parecen brotar como hojas, y las olas del mar se dirigen hacia el horizonte que su mirada señala."
  },
  Skill_4075_BattleDesc_0 = {
    Text = "Aplica [Poison:Arg1] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos y activa el efecto de veneno al [Arg3]%. Obtén [Power:Arg2] puntos de <PowerIconKeywords:Fuerza>."
  },
  Skill_4075_BattleDesc_3 = {
    Text = "Aplica [Poison:Arg1] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos y activa el [Arg3]% de <IntoxicationIconKeywords:veneno>. Obtén [Power:Arg2] puntos de <PowerIconKeywords:Fuerza>. Después, al liberar \"El paso del ego\" en esta batalla, aumenta las capas de <IntoxicationIconKeywords:veneno> en [Poison:Arg4] capas."
  },
  Skill_4075_Desc_0 = {
    Text = "Aplica [Poison:Arg1] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos y activa el efecto de veneno al [Arg3]%. Obtén [Power:Arg2] puntos de <PowerIconKeywords:Fuerza>."
  },
  Skill_4075_Desc_3 = {
