  Skill_4075_OverLimitUtlSkillDesc_0 = {
    Text = "Aplica [Poison:Arg1] acumulaciones de <IntoxicationIconKeywords:Veneno> a todos los enemigos y activa el [Arg3]% del <IntoxicationIconKeywords:Veneno>. Obtén [Power:Arg2] puntos de <PowerIconKeywords:Fortaleza>. El <IntoxicationIconKeywords:Veneno> infligido por Nymphaea aumenta un 50% durante 3 turnos."
  },
  Skill_4075_OverLimitUtlSkillDesc_3 = {
    Text = "Aplica [Poison:Arg1] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos y activa [Arg3]% de <IntoxicationIconKeywords:veneno>. Obtén [Power:Arg2] puntos de <PowerIconKeywords:Fuerza>. Después, al liberar \"el paso del ego\" en esta batalla, aumenta el número de capas de <IntoxicationIconKeywords:veneno> en [Poison:Arg4] capas. Aumenta el <IntoxicationIconKeywords:veneno> causado por Nymphaea en un 50%, durando 3 turnos."
  },
