  Skill_4076_AwakerSkillBackgroundStory = {
    Text = "¡Venus con piel de piel, pisa sobre la espalda del esclavo! \nColoca cadenas en sus cuellos y atraviesa sus corazones desgarrados con agujas espinales"
  },
  Skill_4076_Desc_0 = {
    Text = "A repartir aleatoriamente <Damage:[Damage:Arg1]> puntos de daño [Arg2] veces, con cada daño beneficiado por [Arg4]% de <RetaliateIconKeywords:counter>. Cada ataque disminuye temporalmente los puntos de [Exhaustion:Arg3] del objetivo de <ExhaustionIconKeywords:STR>. <TransitionIconKeywords:leap>: Consume 5 capas de <DreamGuide:dreamlure>. Si tiene éxito, reembolsa el aritmética consumido y causa 2 incidentes adicionales de daño; si no, gana 2 capas de <DreamGuide:dreamlure>."
  },
  Skill_4076_Desc_1 = {
    Text = "Aleatoriamente inflige <Damage:[Damage:Arg1]> puntos de daño [Arg2] veces, este daño se beneficia de [Arg4]% de bono de <RetaliateIconKeywords:counter>, cada ataque reduce los puntos temporales de [Exhaustion:Arg3] del objetivo de <ExhaustionIconKeywords:str>. La tasa de crítico de esta carta se incrementa en un 25%. <TransitionIconKeywords:leap>: Consume 5 capas de <DreamGuide:dreamlure>, si tiene éxito, reintegra el aritmético consumido e inflige daño adicional 2 veces, de lo contrario, gana 2 capas de <DreamGuide:dreamlure>."
  },
  Skill_4076_EffectNameList = {
