  Skill_4137_OverLimitUtlSkillDesc_0 = {
    Text = "Obtén <Posse:[Arg1]> puntos de Llave Plateada. Elige 1 carta del Mazo de robo o del Mazo de Descarte y colócala en tu Mano, haciendo que su Coste de Aritmética sea 0. Aplica <WeaknessIconKeywords:Debilidad> y <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos durante 1 turno. La siguiente Posse liberada surte efecto 2 veces."
  },
  Skill_4137_OverLimitUtlSkillDesc_3 = {
    Text = "Obtén <Posse:[Arg1]> puntos de energía-s llave de plata. Elige 1 carta del mazo de robo o del montón de descarte para poner en tu mano, haciendo que su coste de aritmética sea 0. Baraja 1 <DerivativeCardKeywords_4:\"conocimiento\"> en el mazo de robo. <WeaknessIconKeywords:debilidad> y <VulnerabilityIconKeywords:vulnerable> a todos los enemigos durante 1 turno, el próximo uso de la llave tendrá efecto 2 veces."
  },
  Skill_4138_AwakerSkillBackgroundStory = {
    Text = "Ramona, a la edad de diez años, hizo la solicitud de recibir entrenamiento en combate. \n No era que quisiera jugar a ser caballero, sino que tras ser testigo del derroche y la extravagancia de su padre adoptivo, la niña decidió prepararse para la posible bancarrota que se avecinaba. \n \"El pago por ser escolta de la reina debe ser más alto que el salario de la comisaría, ¿verdad?\""
  },
  Skill_4138_Desc_0 = {
    Text = "Inflige <Damage:[Damage:Arg1]> de daño [Arg2] veces. Al usar, aumenta el número de golpes de \"Espada de la Reina\" en +1, hasta un máximo de [Arg3] veces. Obtiene [Arg7] de maestría temporal en el dominio"
  },
  Skill_4138_Desc_1 = {
    Text = "Inflige <Damage:[Damage:Arg1]> de Daño [Arg5] veces, obteniendo [Power:Arg4] de <PowerIconKeywords:Fuerza> Temporal por cada golpe. Al jugar, aumenta el contador de golpes de \"Espada de la Reina\" en +1, hasta un máximo de [Arg6] veces. Obtén [Arg7] de Maestría temporal de dominio. <RippleKeywords:Réplica>: Obtén Keyflare igual al 300% de la Regeneración de Llave Plateada de Ramona."
  },
  Skill_4138_Desc_3 = {
    Text = "Inflige <Damage:[Damage:Arg1]> de Daño [Arg5] veces, obteniendo [Power:Arg4] de <PowerIconKeywords:Fuerza> Temporal por cada golpe. Al jugar, aumenta el contador de golpes de \"Espada de la Reina\" en +1, hasta un máximo de [Arg6] veces. Obtén [Arg7] de Maestría temporal de dominio. <RippleKeywords:Réplica>: Obtén Keyflare igual al 300% de la Regeneración de Llave Plateada de Ramona."
  },
