  Skill_4144_AwakerSkillBackgroundStory = {
    Text = "Si es una orden del amo, Lily puede lanzar a ese grandote.\nNo le teme al dolor.\nEl dolor es fuerza, el dolor impulsa la furia, Lily no teme al dolor, él tampoco.\nAsí que, puede ayudar al amo a eliminar a los enemigos"
  },
  Skill_4144_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño, activa el efecto de <IntoxicationIconKeywords:veneno> del objetivo en un [Arg3]%, y si se causa un golpe crítico, la tasa se incrementa a [Arg4]%. Se considera un \"golpe\". Por cada capa de <PainWord:Paciencia>, el daño aumenta en 2, y se elimina <PainWord:Paciencia> después de jugar."
  },
  Skill_4144_Desc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño, activa el efecto de <IntoxicationIconKeywords:veneno> en el objetivo del [Arg3]%, y si se causa un golpe crítico, la tasa se incrementa a [Arg4]%. Se considera un \"golpe\". Por cada capa de <PainWord:resistencia>, el daño aumenta en 2, y después de jugar, se elimina <PainWord:resistencia>. Esta carta aumenta la probabilidad de crítico en un 20%."
  },
  Skill_4144_Desc_3 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño, activa el efecto de <IntoxicationIconKeywords:veneno> del [Arg3]%, y si se causa un golpe crítico, la tasa de activación aumenta al [Arg4]%. Se considera un \"golpe\". Por cada capa de <PainWord:paciencia>, el daño aumenta en 2, y después de jugar, se eliminan la mitad de las capas de <PainWord:paciencia>. La probabilidad de crítico de esta carta aumenta en un 20%."
  },
  Skill_4144_EffectNameList = {Text = "Daño"},
