  },
  Skill_4144_tempBattleDesc_2 = {
    Text = "Inflige <Damage:[Damage:Arg1]> puntos de daño, activa el [Arg3] % del efecto de <IntoxicationIconKeywords:Veneno> del objetivo. Si causa un golpe crítico, la proporción activada aumenta a [Arg4] %. Se considera \"Golpe\". Por cada capa de <PainWord:Resistencia>, el daño aumenta en 2. Tras jugarla, elimina la <PainWord:Resistencia>. La probabilidad de crítico de esta carta aumenta en un 20%."
  },
  Skill_4144_tempBattleDesc_3 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño, activa el efecto de <IntoxicationIconKeywords:veneno> del [Arg3]%, y si se causa un golpe crítico, la tasa de activación aumenta al [Arg4]%. Se considera un \"golpe\". Por cada capa de <PainWord:paciencia>, el daño aumenta en 2, y después de jugar, se eliminan la mitad de las capas de <PainWord:paciencia>. La probabilidad de crítico de esta carta aumenta en un 20%."
  },
  Skill_4144_tempBattleDesc_4 = {
    Text = "Inflige <Damage:[Damage:Arg1]> Daño, activa el [Arg3]% del <IntoxicationIconKeywords:Veneno> del objetivo. Si ocurre un Golpe crítico, la tasa de activación aumenta a [Arg4]%. Se considera un \"golpear\". Por cada acumulación de <PainWord:Paciencia>, aumenta el Daño en [Float:Arg6], y elimina la mitad de la <PainWord:Paciencia> tras su uso. Probabilidad de Crítico de esta carta +20%."
  },
