  Skill_4151_Desc = {
    Text = "Causa <Damage:[Damage:Arg1]> de daño [AttackTimes:Arg2] veces, obtiene <Block:[Block:Arg3]> de escudo"
  },
  Skill_4152_AwakerSkillBackgroundStory = {
    Text = "Sangre derramada, cadáveres en todas partes, dolor punzante...\nTodo es un pequeño sacrificio para traer el reino de Dios de nuevo al mundo.\nElla solo lamenta no ser la elegida, la joven encerrada en la jaula"
  },
  Skill_4152_Desc_0 = {
    Text = "Seleccionar 1 despertar y darle <Energy:[Energy:Arg2]> puntos de locura. <O07CardKeyWord:Ritual>: Aumentar locura en [Arg4]/[Arg5]/[Arg6] puntos"
  },
  Skill_4152_Desc_2 = {
    Text = "Selecciona 1 Despertado adicional para que obtenga <Energy:[Energy:Arg2]> puntos de locura, dominio territorial +[Arg3]. <O07CardKeyWord:Rito>: La locura aumenta en [Arg4]/[Arg5]/[Arg6] puntos"
  },
  Skill_4152_EffectNameList = {
    Text = "Alienación"
  },
  Skill_4152_Name = {Text = "El Elegido"},
  Skill_4154_AwakerSkillBackgroundStory = {
    Text = "Escucha, ese es el sonido de la campana fúnebre que suena para ella misma. \n No es una buscadora loca, ni una perdida sin rumbo, solo ha elegido en silencio su camino final. \n Los pétalos marchitos danzan en su ritual, el viento tempestuoso llora por su canto fúnebre. \n Después de ese sonido de campana que resuena en el corazón, el mundo cae brevemente en un silencio mortal."
  },
  Skill_4154_Desc_0 = {
    Text = "Aplica [Poison:Arg1] capas <IntoxicationIconKeywords:veneno> a todos los enemigos, y aplica [Arg2] turnos <WeaknessIconKeywords:debilidad> y <VulnerabilityIconKeywords:vulnerable>"
  },
  Skill_4154_Desc_1 = {
    Text = "Aplicar [Poison:Arg1] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos, aplicar [Arg2] turnos de <WeaknessIconKeywords:debilidad> y <VulnerabilityIconKeywords:vulnerable>, obtener <Block:[Block:Arg3]> puntos de escudo"
  },
  Skill_4154_EffectNameList_0 = {Text = "Veneno"},
