  },
  Skill_4155_AwakerSkillBackgroundStory = {
    Text = "Proveniente de la antigüedad, surgido de la ignorancia, originado en el miedo.\nLo que fluye en las venas de Thais es un instinto primitivo.\nEn un sacrificio del cual es difícil volver, en aquel entonces, la joven Thais fue implantada con este instinto.\nSu voluntad, emociones e incluso su personalidad fueron reemplazadas por una existencia que no le pertenecía—\nlo único que dejó es este instinto común entre los seres vivos, el miedo a la muerte."
  },
  Skill_4155_BattleDesc_0 = {
    Text = "<EmbryoFusionIconKeywords:Fusión Embrionaria> +[Blood:Arg1], obtén <Posse:[Arg2]> Keyflare. Elige: <B01AFKeyWord1:Sangre del miedo>, <B01AFKeyWord2:Sangre de descomposición>, <B01AFKeyWord3:Sangre de coito><DerivativeCardKeywords_149:><DerivativeCardKeywords_150:><DerivativeCardKeywords_151:>"
  },
  Skill_4155_BattleDesc_1 = {
    Text = "<EmbryoFusionIconKeywords:Fusión Embrionaria> +[Blood:Arg1], obtén <Posse:[Arg2]> Keyflare. Elige: <B01AFKeyWordQ1:Sangre del miedo>, <B01AFKeyWordQ2:Sangre de descomposición>, <B01AFKeyWordQ3:Sangre de coito><DerivativeCardKeywords_149:><DerivativeCardKeywords_150:><DerivativeCardKeywords_151:>"
  },
  Skill_4155_Desc_0 = {
    Text = "<EmbryoFusionIconKeywords:Fusión Embrionaria> +[Blood:Arg1], obtén Keyflare igual a 2× la Regeneración de Llave Plateada de Thais. Elige: <B01AFKeyWord1:Sangre del miedo>, <B01AFKeyWord2:Sangre de descomposición>, <B01AFKeyWord3:Sangre de coito><DerivativeCardKeywords_149:><DerivativeCardKeywords_150:><DerivativeCardKeywords_151:>"
  },
  Skill_4155_Desc_1 = {
