    Text = "El instinto de la sangre sagrada"
  },
  Skill_4156_AwakerSkillBackgroundStory = {
    Text = "Mientras era lectora acompañante, Horla ya disfrutaba esconderse en un rincón del estudio para leer poemas. Esas líneas de poesía lamentosa siempre lograban conmoverla"
  },
  Skill_4156_BattleDesc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Obtén <Energy:[Energy:Arg2]> puntos de Aliemus. Se considera \"Defensa\". <TransitionIconKeywords:Impulso>: Cambia a la emoción \"Ai\"."
  },
  Skill_4156_BattleDesc_1 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Obtén <Energy:[Energy:Arg2]> puntos de Aliemus. Aplica 1 capa de <WeaknessIconKeywords:Síntoma: Debilidad> a todos los enemigos. Se considera \"Defensa\". <TransitionIconKeywords:Impulso>: Cambia a la emoción \"Ai\"."
  },
  Skill_4156_Desc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Horla obtiene <Energy:[Energy:Arg2]> puntos de Aliemus. Se considera \"Defensa\". <TransitionIconKeywords:Impulso>: Cambia a la emoción \"Ai\". Por cada capa de metáfora \"Ai\" consumida, recupera <Heal:[Heal:Arg3]> puntos de vida."
  },
  Skill_4156_Desc_1 = {
