  Skill_4306_AwakerSkillBackgroundStory = {
    Text = "Actuará en la tierra en su nombre.\nGanarás su buen nombre.\nEn la destrucción, soportará el dolor irremediable.\nAsí es el sustituto"
  },
  Skill_4306_Desc_0 = {
    Text = "Miryam gana <Energy:[Energy:Arg1]> puntos de aliemus. <ExaltIconKeywords:Rouse>: Límite de tentáculos y recuento de tentáculos +1, inflige 1 capa de <WeaknessIconKeywords:Weakness> y <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos. La tasa de crítico de \"Golpe\" y \"Pira Exaltada\" de Miryam aumenta en un 100%. Obtiene 1 carta de <O07CardKeyWord4:\"Fe Herética\"> en mano."
  },
  Skill_4306_Desc_15 = {
    Text = "Miryam obtiene <Energy:[Energy:Arg1]> de Aliemus. <ExaltIconKeywords:Activar>: Límite de tentáculos y Número de Tentáculos +1. Inflige 1 acumulación de <WeaknessIconKeywords:Síntoma: Debilidad> y <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos. Probabilidad de Crítico de \"golpear\" y \"Pira exaltada\" de Miryam +100%. Coloca 1 <O07CardKeyWord4:\"Fe herética\"> en la mano. Por cada 2 cartas de \"Sacramento\" volteadas, coloca 1 \"Fantasma del Reino Divino\" en la mano."
  },
