  Skill_4310_Desc = {
    Text = "Causa <Damage:[Damage:Arg1]> de daño [AttackTimes:Arg2] veces. El oponente pierde [Arg3] de <PowerIconKeywords:fuerza> hasta el final del turno"
  },
  Skill_4311_AwakerSkillBackgroundStory = {
    Text = "¿Te sentirás amado con un suave toque? \n¿Te perderás en mí con un aliento cálido? \n¿Este acariciar rodeado de perlas y tules es un regalo para ti?"
  },
  Skill_4311_Desc_0 = {
    Text = "Seleccionar 1 despertar y ambos obtienen <Energy:[Energy:Arg1]> puntos de locura. Obtener [Power:Arg2] puntos de <PowerIconKeywords:Fuerza>"
