  Skill_4313_Desc = {
    Text = "Aplica [Arg1] capas de <IntoxicationIconKeywords:Veneno>"
  },
  Skill_4313_Name = {Text = "Toxina"},
  Skill_4314_AwakerSkillBackgroundStory = {
    Text = "Su sangre arde por ellos, su cerebro hierve por ellos.\nSin importar si estos hijos de lo extraño pueden cumplir su deseo, o si pueden perdurar en la ilusión.\nThais acoge con amor el nacimiento de cada hijo sagrado"
  },
  Skill_4314_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: hace que otros Despertados obtengan <Energy:[Energy:Arg1]> puntos de alienación.] Causa <Damage:[Damage:Arg2]> puntos de daño a todos los enemigos, infligiendo <BleedingIconKeywords:sangrar> equivalente a [Arg3]% del daño causado, y aplica <IntoxicationIconKeywords:veneno> equivalente a [Arg4]% del daño causado y obtiene <RetaliateIconKeywords:contrataque> equivalente a [Arg5]% del daño causado. Elige 1 carta de comando no derivada en tu mano, coloca [Arg7] <plural value=\"[Arg7]\" singular=\"copia original\" plural=\"copias originales\"> con <DepleteIconKeywords:consumo>, <NothingnessIconKeywords:Oblivion> y -[Arg6] de coste de aritmética en tu mano."
  },
  Skill_4314_EffectNameList = {
    Text = "Frenesí, daño, porcentaje de sangrado, porcentaje de veneno, porcentaje de contraataque"
  },
  Skill_4314_Name = {
    Text = "Ritual de la Abundancia"
  },
  Skill_4314_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: hace que otros Despertados obtengan <Energy:[Energy:Arg1]> puntos de locura.]Inflige <Damage:[Damage:Arg2]> puntos de daño a todos los enemigos, infligiendo <BleedingIconKeywords:sangrar> del [Arg3]% de daño, y aplicando <IntoxicationIconKeywords:veneno> del [Arg4]% de daño y obteniendo <RetaliateIconKeywords:contrataque> del [Arg5]% de daño. Elige 1 carta de comando no derivada en tu mano, coloca [Arg7] copias originales con <DepleteIconKeywords:consumo> y <NothingnessIconKeywords:ilusión> en tu mano, reduciendo su coste de aritmética en -[Arg6]. En los próximos 3 turnos, al comienzo de cada turno, transforma 1 \"embrión\" en \"vástago de la pureza\", si no hay \"embrión\", <EmbryoFusionIconKeywords:Fusión Embrionaria> +[Blood:Arg8], sin verse afectado por el efecto de mejora de Fusión Embrionaria."
  },
  Skill_4314_PropertyNameList = {
    Text = "$GrowValue1, ataque*GrowValue2, $GrowValue3, $GrowValue4, $GrowValue5"
  },
  Skill_4315_AwakerSkillBackgroundStory = {
    Text = "Protégeme. Protégeme. Protégeme.\nMonstruo cobarde, como ella, parece tener vida, pero sin conciencia.\nEl limo negro se convierte en sus sirvientes, obedeciendo órdenes día y noche"
  },
  Skill_4315_Desc_0 = {
    Text = "Lily gana <Energy:[Energy:Arg1]> puntos de aliemus. <ExaltIconKeywords:despertar>: Al comienzo del turno, recibe el <PainWord:resistir> del 10% de la salud máxima. Cuando Lily aplica un escudo, inflige [Poison:Arg2] capas <IntoxicationIconKeywords:veneno> al enemigo con más vida"
  },
  Skill_4315_Desc_15 = {
    Text = "Lily obtiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Despertar>: Al inicio del turno, obtén <PainWord:Paciencia> igual al 10% de los PV Max. Cuando Lily aplica un Escudo del personaje, inflige [Poison:Arg2] Acumulaciones de <IntoxicationIconKeywords:Veneno> al enemigo con más PV. Exaltar hace que cada golpe recibido en este turno aumente el efecto de consumo de <PainWord:Paciencia> de la siguiente \"Huelga para proteger\" en un 40%, acumulable hasta 5 veces."
  },
  Skill_4315_EffectNameList = {
