  Skill_4322_AwakerSkillBackgroundStory = {
    Text = "Las polillas no tienen cerebro, solo siguen sus instintos.\nSi es así, dejemos que estos idiotas vean lo que codician.\nEs el sueño inocente de una joven"
  },
  Skill_4322_Desc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo, añade 1 carta de <DepleteIconKeywords:Consumo> <DerivativeCardKeywords_18:\"Llamas verdes\"> a tu mano. <TransitionIconKeywords:Impulso>: Antes de que comience el siguiente turno, cada vez que recibas 1 ataque, añade 1 carta de <DepleteIconKeywords:Consumo> <DerivativeCardKeywords_18:\"Llamas verdes\"> a tu mano."
