  Skill_4328_Name = {
    Text = "Infusión tóxica"
  },
  Skill_4329_AwakerSkillBackgroundStory = {
    Text = "Incluso si ella fue testigo de la destrucción de su tierra natal, incluso si todo lo que conocía ha desaparecido por completo bajo la disolución, no estaba dispuesta a renunciar a la búsqueda. El dispositivo de localización iluminó la luz de búsqueda, tratando de encontrar a aquellos que compartían su hogar. \n Seguro que habrá, seguro que habrá."
  },
  Skill_4329_BattleDesc_0 = {
    Text = "Obtén <Block:[Block:Arg3]> puntos de blindaje, descarta todas las cartas en la mano. <TransitionIconKeywords:Impulso>: No descartar cartas, obtén <Block:[Block:Arg4]> puntos de blindaje y roba 1 carta."
  },
  Skill_4329_BattleDesc_2 = {
    Text = "Obtener <Block:[Block:Arg3]> puntos de blindaje, descarta todas las cartas en la mano, por cada carta descartada, obtén <Block:[Block:Arg2]> puntos de escudo de latencia. <TransitionIconKeywords:Impulso>: No descartar cartas, obtén <Block:[Block:Arg4]> puntos de blindaje y roba 2 cartas."
  },
  Skill_4329_Desc_0 = {
    Text = "Obtener <Block:[Block:Arg1]> puntos de escudo, descarta todas las cartas en la mano, por cada carta descartada, el escudo aumenta un 50%. <TransitionIconKeywords:Salto>: No descartar cartas y roba 1 carta, el escudo aumenta un 100%"
  },
  Skill_4329_Desc_2 = {
    Text = "Gana <Block:[Block:Arg1]> puntos de escudo, descarta todas las cartas en la mano, cada carta descartada aumenta el escudo ganado en un 50% y gana <Block:[Block:Arg2]> puntos de escudo retrasado. <TransitionIconKeywords:leap>: Ya no descartar cartas y roba 2 cartas, el escudo ganado se incrementa en un 100%."
  },
