  Skill_4332_Desc = {
    Text = "Inflige <Damage:[Damage:Arg1]> de daño [AttackTimes:Arg2] veces"
  },
  Skill_4333_Desc = {
    Text = "Obtener [Arg1] puntos de <PowerIconKeywords:fuerza> y <Block:[Block:Arg2]> puntos de escudo"
  },
  Skill_4334_AwakerSkillBackgroundStory = {
    Text = "El capullo que florece en el lodo negro. También había sentido el cuidado del jardinero y había sido acariciado por el rocío de la lluvia. \n Pero en este momento, florece en soledad, permitiendo que el viento huracanado corte su delicada piel, permitiendo que la lluvia torrencial golpee su frágil cuerpo, permitiendo que la delgada y afilada hoja corte su superficie, y que la larga y afilada aguja penetre en su médula. \n Al fin y al cabo, el enorme monstruo que habita en su interior, protegerá su cuerpo del dolor. \n Quizás, lo único que la acompaña, es ese enorme monstruo, a partir de ahora, solo podrá estar con el monstruo..."
  },
  Skill_4334_BattleDesc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% ([Arg3]) de las capas <PainWord:resistencia> y elimina <PainWord:resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas <IntoxicationIconKeywords:veneno> al atacante durante 1 turno."
  },
  Skill_4334_BattleDesc_3 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% ([Arg3]) de las capas <PainWord:resistencia> y elimina la mitad de <PainWord:resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas <IntoxicationIconKeywords:veneno> al atacante durante 1 turno."
  },
  Skill_4334_Desc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% de los puntos de <PainWord:resistencia> y elimina la <PainWord:resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas de <IntoxicationIconKeywords:veneno> al atacante durante 1 turno."
  },
  Skill_4334_Desc_3 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% de las capas <PainWord:resistencia> y elimina la mitad de las capas <PainWord:resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas <IntoxicationIconKeywords:veneno> al atacante durante 1 turno."
  },
  Skill_4334_EffectNameList_0 = {
    Text = "Escudo, veneno"
