    Text = "Flor inmortal sobre limo"
  },
  Skill_4334_OverLimitUtlSkillDesc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de Blindaje. Recupera PV equivalente al [Arg2]% ([Arg3]) de las acumulaciones de <PainWord:Paciencia> y elimina la <PainWord:Paciencia>. Por cada Ataque recibido, aplica [Poison:Arg4] acumulaciones de <IntoxicationIconKeywords:Veneno> al atacante durante 1 turno. En esta batalla, el límite máximo de Paciencia aumenta un 100% y se obtiene Paciencia equivalente al PV Max. Coloca en tu Mano 2 cartas de \"Huelga para proteger\" con Consumo añadido."
  },
  Skill_4334_OverLimitUtlSkillDesc_3 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% ([Arg3]) de las capas <PainWord:Paciencia> y elimina la mitad de <PainWord:Paciencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas <IntoxicationIconKeywords:veneno> al atacante durante 1 turno. Aumenta el límite de paciencia en un 100% en esta batalla y obtén la paciencia equivalente a la salud máxima. Coloca 2 cartas de \"Huelga para proteger\" con consumo adicional en tu mano."
  },
