  },
  Skill_4334_tempBattleDesc_1 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% ([Arg3]) de las capas <PainWord:resistencia> y elimina <PainWord:resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas <IntoxicationIconKeywords:veneno> al atacante durante 1 turno."
  },
  Skill_4334_tempBattleDesc_2 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% ([Arg3]) de las capas <PainWord:resistencia> y elimina la mitad de <PainWord:resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas <IntoxicationIconKeywords:veneno> al atacante durante 1 turno."
  },
  Skill_4334_tempBattleDesc_3 = {
    Text = "Obtiene <Block:[Block:Arg1]> puntos de escudo. Recupera vida equivalente al [Arg2] %([Arg3]) de las capas de <PainWord:Resistencia> y elimina la mitad de <PainWord:Resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas de <IntoxicationIconKeywords:Veneno> al atacante durante 1 turno. Por cada ataque recibido este turno, el efecto de consumo de <PainWord:Resistencia> del siguiente \"Golpe de Retribución\" aumenta en un 40%, acumulable hasta 5 capas."
  },
  Skill_4334_tempOverLimitUtlSkillDesc_1 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de Blindaje. Recupera PV equivalente al [Arg2]% ([Arg3]) de las acumulaciones de <PainWord:Paciencia> y elimina la <PainWord:Paciencia>. Por cada Ataque recibido, aplica [Poison:Arg4] acumulaciones de <IntoxicationIconKeywords:Veneno> al atacante durante 1 turno. En esta batalla, el límite máximo de Paciencia aumenta un 100% y se obtiene Paciencia equivalente al PV Max. Coloca en tu Mano 2 cartas de \"Huelga para proteger\" con Consumo añadido."
