  Skill_4334_tempOverLimitUtlSkillDesc_2 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Recupera el [Arg2]% ([Arg3]) de las capas <PainWord:Paciencia> y elimina la mitad de <PainWord:Paciencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas <IntoxicationIconKeywords:veneno> al atacante durante 1 turno. Aumenta el límite de paciencia en un 100% en esta batalla y obtén la paciencia equivalente a la salud máxima. Coloca 2 cartas de \"Huelga para proteger\" con consumo adicional en tu mano."
  },
  Skill_4334_tempOverLimitUtlSkillDesc_3 = {
    Text = "Obtiene <Block:[Block:Arg1]> puntos de escudo. Recupera vida equivalente al [Arg2] %([Arg3]) de las capas de <PainWord:Resistencia> y elimina la mitad de <PainWord:Resistencia>. Por cada ataque recibido, aplica [Poison:Arg4] capas de <IntoxicationIconKeywords:Veneno> al atacante durante 1 turno. El límite máximo de Resistencia aumenta en un 100% durante esta batalla, y se obtiene Resistencia equivalente a la vida máxima. Coloca 2 cartas de \"Golpe de Retribución\" con Consumo añadido en la mano. Por cada ataque recibido este turno, el efecto de consumo de <PainWord:Resistencia> del siguiente \"Golpe de Retribución\" aumenta en un 40%, acumulable hasta 5 capas."
  },
