  Skill_4339_AwakerSkillBackgroundStory = {
    Text = "Alguna vez alguien preguntó medio en broma si Aigis podía tejerle una bufanda, ya que tenía todo lo que necesitaba, desde agujas de tejer hasta hilo. \n Aigis bajó la cabeza, avergonzada. No les dijo a los demás que la aguja de tejer en su cabeza no era un adorno, sino un dispositivo especial que suprimía el poder de sus ojos. \n Unos días después, completó una bufanda de colores con la aguja de tejer que había pedido prestada."
  },
  Skill_4339_Desc_0 = {
    Text = "Eigis obtiene <Energy:[Energy:Arg1]> puntos de locura. <ExaltIconKeywords:despertar> : tras jugar una carta, Eigis aplica [Arg2] por turnos a todos los enemigos <VulnerabilityIconKeywords:vulnerable>"
