  Skill_4374_Name = {Text = "Herida"},
  Skill_4375_AwakerSkillBackgroundStory = {
    Text = "Paso a paso, ella avanzó lentamente hacia el agua del mar. \n El mar de la noche, que apenas tocaba su piel y parecía un poco frío, en este momento se sentía cálido como un abrazo humano. \n El mar me acogió, este pensamiento flotó silenciosamente en la mente de Nymphaea. \n En un instante, vio la sonrisa de sus padres. En lo profundo del mar, debe haber una dicha familiar."
  },
  Skill_4375_Desc_0 = {
    Text = "Nymphaea gana <Energy:[Energy:Arg1]> puntos de Aliemus. <ExaltIconKeywords:Gnosis Rouse>: Después de que Nymphaea juegue una carta, gana <Energy:[Energy:Arg2]> puntos de Aliemus. Al final del turno, aumenta el Veneno causado por Nymphaea en [Arg3]%."
