  Skill_4403_AwakerSkillBackgroundStory = {
    Text = "Incontables engranajes se superponen y se impulsan mutuamente, otorgando a la carcasa de porcelana la capacidad de imitar la vida.\nEsta es su obra más orgullosa, un instrumento exquisito que no puede ser replicado.\nErica nunca podría haber imaginado que este autómata que lleva su mismo nombre se convertiría en su segunda vida."
  },
  Skill_4403_Desc_0 = {
    Text = "Erika obtiene <Energy:[Energy:Arg1]> puntos de aliemus. <ExaltIconKeywords: Despertar de la Gnosis>: Cuando Erika causa daño, obtiene [Power:Arg2] puntos temporales de <PowerIconKeywords: Poder>; cuando Erika otorga un escudo, obtiene [Arg3] puntos temporales de <AlertIconKeywords: Alerta>"
  },
  Skill_4403_Desc_15 = {
    Text = "Erica obtiene <Energy:[Energy:Arg1]> puntos de Aliemus. <ExaltIconKeywords:Despertar>: Cuando Erica causa daño, obtiene [Power:Arg2] puntos temporales de <PowerIconKeywords:Fortaleza>; cuando Erica otorga un escudo, obtiene [Arg3] puntos temporales de <AlertIconKeywords:Alerta>. Tras desatar Exaltar, su Exaltar recibe adicionalmente un bono de 1x de Fortaleza y Alerta."
