  Skill_4407_AwakerSkillBackgroundStory = {
    Text = "Su piel se volvió verde, las venas en descomposición se retorcían y se enrollaban sin parar.\nSu hombro parecía estar gestando algo—un líquido negro fluía por su brazo, propagándose sobre la mesa de operaciones.\nLa carne y sangre nacida brotaba de la herida, compitiendo entre sí, suave y silenciosa.\nLa niña débil sonrió.\n\"Finalmente nos volvemos a ver, @2.\""
  },
  Skill_4407_Desc_0 = {
    Text = "Causa aleatoriamente <Damage:[Damage:Arg1]> de daño [Arg2] veces. Hasta el inicio del próximo turno, por cada 2 puntos de vida perdidos, obtiene 1 escudo al inicio del próximo turno"
