  Skill_4579_AwakerSkillBackgroundStory = {
    Text = "El hechicero dijo: «Los paganos son numerosos\n y nosotros, los levantinos, parecemos débiles.\n Hermano Uvhash, toca tu trompeta,\n y lucha como un loco.»\n El guerrero respondió: «Aquí no hay paganos.\n Todos ustedes serán asesinados por mí, los muertos no distinguen entre razas o creencias.\n En ese momento, los cadáveres cubrirán el valle y llenarán la cima de la montaña,\n y será mi ofrenda al Himno de sangre y arena.»"
  },
  Skill_4579_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: El daño de \"Himno de sangre y arena\" liberado posteriormente en esta batalla se incrementa en [Arg4] puntos, y el multiplicador de fuerza aumenta en [Arg3] veces.]Causa <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos. <PowerIconKeywords:Fuerza> tiene un efecto de [Arg2] veces en \"Himno de sangre y arena\". Uvhash gana <Energy:[Energy:Arg5]> puntos de alienación."
  },
  Skill_4579_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: El daño de \"Himno de sangre y arena\" liberado posteriormente en este combate aumenta en [Arg4] puntos, y el multiplicador de fuerza aumenta en [Arg3] veces.] Causa <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos. <PowerIconKeywords:Fuerza> tiene un efecto de [Arg2] veces en \"Himno de sangre y arena\". Obtiene Alienación equivalente a 2 veces la Carga de Alienación de Uvhash."
  },
  Skill_4579_EffectNameList = {
    Text = "Daño, aumento de daño"
  },
  Skill_4579_Name = {
    Text = "Himno de sangre y arena"
  },
  Skill_4579_OverLimitUtlSkillDesc = {
    Text = "[<DevouredIconKeywords:Devorar>: El daño de \"Himno de sangre y arena\" liberado posteriormente en esta batalla aumenta en [Arg4] puntos, y el multiplicador de fuerza aumenta en [Arg3] veces.]Causa <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos. <PowerIconKeywords:Fuerza> tiene un efecto de [Arg2] veces en \"Himno de sangre y arena\". Uvhash gana <Energy:[Energy:Arg5]> puntos de alienación. Llena la mano con \"¡Chillido, sangre!\" adicional con vacío y consumo. El número de ataques de Uvhash aumenta en 1 en este turno."
  },
  Skill_4579_PropertyNameList = {
