  Skill_4581_AwakerSkillBackgroundStory = {
    Text = "Debajo de la iglesia hay un espacio oculto.\n\nEl alfil se arrodilla ante la pizarra, recitando el murmurio dejado desde el inicio de la creación.\n\nLas runas olvidadas por el tiempo emiten una luz de respuesta, y a la voluntad del alfil aparece una enorme sombra, otorgando la \"Bendición\" del Creador a aquellos que están cubiertos por su resplandor."
  },
  Skill_4581_Desc_0 = {
    Text = "[<DevouredIconKeywords:devorar>:obtiene [Power:Arg1] puntos de <PowerIconKeywords:poder> temporal, la tasa de crítico temporal aumenta en +[Arg4]%.]Obtiene <Block:[Block:Arg2]> puntos de escudo. <VulnerabilityIconKeywords:vulnerable> a todos los enemigos durante 1 turno. Hasta que comience el siguiente turno, al recibir daño, se convertirá en recuperación del Horno Carmesí el [Arg3]% del daño."
  },
  Skill_4581_Desc_3 = {
    Text = "[<DevouredIconKeywords:Devorar>: obtiene [Power:Arg1] puntos de <PowerIconKeywords:fuerza> temporal, la tasa crítica temporal aumenta en +[Arg4]%.] Obtén <Block:[Block:Arg2]> puntos de escudo. Aplica <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos por 1 turno. Hasta el comienzo del siguiente turno, al recibir daño, convertirá el [Arg3]% del daño en puntos de recuperación del Horno Carmesí. Salvador obtiene [Arg5]% de daño crítico temporal."
  },
  Skill_4581_EffectNameList = {
    Text = "Fuerza temporal, escudo, cantidad de conversión del Horno Carmesí"
  },
  Skill_4581_Name = {
    Text = "Bendición del Creador"
  },
  Skill_4581_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar>: Obtén [Power:Arg1] puntos de <PowerIconKeywords:Fortaleza> Temporal, Tasa de Crítico Temporal +[Arg4]%.] Obtén <Block:[Block:Arg2]> puntos de Blindaje. Aplica <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos durante 1 turno. Hasta el inicio del siguiente turno, al recibir un Ataque, convierte el [Arg6]% del Daño recibido en recuperación del Horno Carmesí. Hace que el \"Golpe Básico\" y \"Fin del sufrimiento\" de Salvador disfruten adicionalmente de un 100% de bonificación de Fortaleza. En esta exploración, el límite máximo del Horno Carmesí aumenta un 2% del PV Max, hasta un máximo del 10%."
  },
  Skill_4581_OverLimitUtlSkillDesc_3 = {
    Text = "[<DevouredIconKeywords:Devorar>:Obtén [Power:Arg1] puntos temporales <PowerIconKeywords:Fuerza> y aumenta la tasa crítica temporal en +[Arg4]%.]Obtén <Block:[Block:Arg2]> puntos de blindaje. <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos durante 1 turno. Hasta el inicio del siguiente turno, al recibir daño, se convierte en un [Arg6]% de curación del Horno Carmesí. Salvador obtiene un [Arg5]% de daño crítico temporal. Los ataques básicos de Salvador, \"golpear\" y \"Fin del sufrimiento\", reciben un bono adicional de poder equivalente al 100%. Durante esta exploración, el límite máximo del Horno Carmesí aumenta en un 2% de su vida máxima, hasta un máximo del 10%."
  },
  Skill_4581_PropertyNameList = {
    Text = "Poder de ataque*GrowValue1,DEF*GrowValue2,$GrowValue3%"
  },
