  Skill_4615_AwakerSkillBackgroundStory = {
    Text = "Faint es imperfecta.\nFaint es peligrosa.\nFaint es maldita.\nFaint es el color más enigmático y vibrante de las estrellas."
  },
  Skill_4615_BattleDesc_15 = {
    Text = "Faint obtiene <Energy:[Energy:Arg1]> Alienación. <ExaltIconKeywords:Despertar>: Inmediata y permanentemente <TouquKeywords:Roba> [Arg4] <PowerIconKeywords:STR> de todos los enemigos. Obtén [Counterattack:Arg3] <plural value=\"[Counterattack:Arg3]\" singular=\"Acumulación\" plural=\"Acumulaciones\"> de <RetaliateIconKeywords:Contrataque>. La tasa de decaimiento de Resistencia a la muerte en esta batalla se reduce del 50% al 45%. Cuando Faint juega una carta, <TouquKeywords:Roba> [Arg2] <PowerIconKeywords:STR> de todos los enemigos. Al final del turno, inflige <RealDamage:Daño Fijo> igual al 50% del <RetaliateIconKeywords:Contrataque> de Faint."
  },
  Skill_4615_Desc_0 = {
    Text = "Faint gana <Energy:[Energy:Arg1]> Alienación. <ExaltIconKeywords:Activar>: Gana [Counterattack:Arg3] Acumulaciones de <RetaliateIconKeywords:Contador>. La tasa de decaimiento de la Resistencia a la muerte se reduce del 50% al 45% durante esta batalla. Cuando Faint juega una carta, <TouquKeywords:Roba> [Arg2] <PowerIconKeywords:STR> de todos los enemigos. Al final del turno, inflige <RealDamage:Daño Fijo> igual al 50% del <RetaliateIconKeywords:Contador> de Faint."
  },
  Skill_4615_Desc_15 = {
