  Skill_4658_AwakerSkillBackgroundStory = {
    Text = "Las manos de Casiah están vacías;  \nel sombrero de Casiah está vacío;  \nel pecho de Casiah está vacío.  \nLa vacía Casiah contenía una vacía alegría, realizando una vacía actuación en un vacío carnaval"
