  Skill_4660_AwakerSkillBackgroundStory = {
    Text = "Uno, dos, uno, dos... \n Ella sostiene una bandeja, moviéndose con un ritmo alegre entre la multitud. \n Los invitados no dejan de beber y cantar, ella no deja de servir y sonreír. \n Aquí todo es dorado. Un salón dorado, vino dorado, y el vuelo dorado de su falda. \n Karen ama el dorado. Ella levanta su sonrisa característica, practicada innumerables veces. \n \"¡Invitados, disfruten su comida——!!\""
  },
  Skill_4660_Desc_0 = {
    Text = "Elimina el estado de <SlowIconKeywords:lento> de todas las cartas en mano. Recupera <Heal:[Heal:Arg1]> puntos de vida. Añade 1 carta de <DerivativeCardKeywords_42:\"Plato Maravilloso\"> a tu mano. Aplica [Poison:Arg2] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos"
