  },
  Skill_4660_OverLimitUtlSkillDesc_0 = {
    Text = "Elimina el Estado de <SlowIconKeywords:Estancamiento> de todas las cartas de la Mano. Cicatrización de <Heal:[Heal:Arg1]> puntos de PV. Coloca 1 carta de <DerivativeCardKeywords_43:\"Cocina maravillosa\"> en la Mano. Aplica [Poison:Arg2] capas de <IntoxicationIconKeywords:Veneno> a todos los enemigos. Baraja 1 carta de <DerivativeCardKeywords_42:\"Cocina maravillosa\"> en el Mazo de robo y 1 en el Mazo de Descarte."
  },
  Skill_4660_OverLimitUtlSkillDesc_3 = {
    Text = "Elimina el estado de <SlowIconKeywords:lento> de todas las cartas en mano. Recupera <Heal:[Heal:Arg1]> puntos de vida. Añade 1 carta de <DerivativeCardKeywords_43:\"Cocina maravillosa\"> a tu mano. Aplica [Poison:Arg2] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos. Mezcla 1 carta de <DerivativeCardKeywords_43:\"Cocina maravillosa\"> en la pila de robar y la pila de descarte."
