  Skill_4663_AwakerSkillBackgroundStory = {
    Text = "La fría máquina reemplazó al corazón, y el aceite en los tubos hidráulicos reemplazó a la sangre. Ella debería ser fría, racional y actuar según las órdenes. \n Pero, una voluntad externa se movía silenciosamente dentro de su cuerpo. No necesita sangre, ni temperatura, solo con su propia existencia puede arder con malicia inhumana. Él dijo: ¡Sométete, criatura despreciable y débil, y luego destrúyete en mi esfera eléctrica ardiente."
  },
  Skill_4663_BattleDesc_0 = {
    Text = "Obtén [Power:Arg1] puntos temporales de <PowerIconKeywords:fuerza>. Obtén <Posse:[Arg2]> puntos de llave plateada. Disipa el estado de <WeaknessIconKeywords:debilidad>. Cada vez que una carta entra en el <DimensionalSpaceIconKeywords:espacio hiperspacial>, transfórmala en <DerivativeCardKeywords_14:\"Retraer: Mecha\">."
  },
  Skill_4663_BattleDesc_1 = {
    Text = "Obtén [Power:Arg1] puntos temporales de <PowerIconKeywords:fuerza>. Obtén <Posse:[Arg2]> puntos de llave plateada. Disipa el estado de <WeaknessIconKeywords:debilidad>. Coloca en tu mano 1 carta de \"golpear\" con <DepleteIconKeywords:consumo> de Erica. Cada vez que una carta entra en el <DimensionalSpaceIconKeywords:espacio hiperspacial>, transfórmala en <DerivativeCardKeywords_14:\"Recoger: Mecha\">."
  },
  Skill_4663_Desc_0 = {
    Text = "Obtén [Power:Arg1] puntos temporales de <PowerIconKeywords:fuerza>. Obtén energía-s de llave plateada equivalente a la regeneración de llave plateada de Erica. Disipa tu estado de <WeaknessIconKeywords:debilidad>. Cada vez que una carta entra en <DimensionalSpaceIconKeywords:espacio hiperspacial>, transfórmala en <DerivativeCardKeywords_14:\"Armadura Mecánica - Recoger\">."
  },
  Skill_4663_Desc_1 = {
    Text = "Obtén [Power:Arg1] puntos temporales de <PowerIconKeywords:fuerza>. Obtén una cantidad equivalente de energía de llave plateada de la regeneración de llave plateada de Erica. Disipa el estado de <WeaknessIconKeywords:debilidad>. Coloca en tu mano 1 carta de \"golpe\" de Erica que tenga <DepleteIconKeywords:consumo>. Cada vez que una carta entra en el <DimensionalSpaceIconKeywords:espacio hiperspacial>, transfórmala en <DerivativeCardKeywords_14:\"Recoger: Mecha\">."
  },
