  Skill_4664_AwakerSkillBackgroundStory = {
    Text = "La enfermedad invisible llega en silencio, trayendo un dolor y locura infinitos. \n\n El alfil no puede dormir por la noche, profundamente apenado por no poder aliviar el sufrimiento de la gente. \n\n\"Oh, Creador misericordioso, sálvalos, estoy dispuesto a asumir todo el dolor y la tristeza por ellos.\"\n\n Entonces el Padre Dios le otorgó la \"Bendición\", permitiéndole llevar la pizarra grabada con la Palabra de Dios, para llevar a cabo actos de alivio y mitigación del sufrimiento."
  },
  Skill_4664_Desc_0 = {
    Text = "Salvador obtuvo <Energy:[Energy:Arg1]> puntos de locura. <ExaltIconKeywords:despertar>: Pon 1 carta <B02AFKeyWord:el amor es protección> en tu mano. Al final del turno, recibe [Power:Arg2] puntos de <PowerIconKeywords:poder>"
  },
  Skill_4664_Desc_15 = {
    Text = "Salvador obtiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Despertar>: Coloca 1 <B02AFKeyWord:Santuario de la Misericordia> en la mano. Al final del turno, obtiene [Power:Arg2] <PowerIconKeywords:FUE>. El Horno Carmesí acumulado por \"Bendición del Creador\" y \"Benditos sean los huesos\" +25%, y cuando se selecciona \"Liberación\" para \"Fin del sufrimiento,\" cada 1% de PV Max consumido del Horno Carmesí otorga +5% de Daño Final."
  },
