  Skill_4667_AwakerSkillBackgroundStory = {
    Text = "Es un enorme laberinto que trasciende todas las dimensiones.\nLos viajeros que se pierden en el laberinto deben enfrentar un trato grosero.\nSi responden \"no\", quedarán atrapados en el laberinto para siempre.\nSi responden \"sí\", les implantarán un heredero profano y se borrarán todos sus recuerdos.\n¿Qué, preguntas cuál es el contenido específico del trato?\nNadie sabe el contenido específico del trato, ni siquiera el pálido Señor del laberinto.\nUn trato es solo un trato."
  },
  Skill_4667_Desc_0 = {
    Text = "[<DevouredIconKeywords:devorar>：obtiene [Power:Arg1] puntos de <PowerIconKeywords:poder> y [Arg4] puntos de <AlertIconKeywords:alerta>.]Obtiene <Block:[Block:Arg2]> puntos de escudo. Aplica [Poison:Arg3] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos"
