  },
  Skill_4667_OverLimitUtlSkillDesc_0 = {
    Text = "[<DevouredIconKeywords:devorar>:obtiene [Power:Arg1] puntos de <PowerIconKeywords:poder> y [Arg4] puntos de <AlertIconKeywords:alerta>.]Obtén <Block:[Block:Arg2]> puntos de blindaje. Aplica [Poison:Arg3] capas de <IntoxicationIconKeywords:veneno> a todos los enemigos. Roba 2 cartas de comando de defensa no golpe de Agrippa, reduce el coste de aritmética de 2 cartas de comando de defensa no golpe de Agrippa en este turno en -1."
  },
