  Skill_4694_AwakerSkillBackgroundStory = {
    Text = "En la oscura prisión de Nueva Puerta, el aceite de cera que se encuentra por todas partes en Londinium también es un bien raro.\nDado que es raro, debe ser utilizado en momentos clave, como en el castigo, sobre la piel de los niños desobedientes.\nNo es un aceite de cera especial, cae acompañado de lamentos y gritos trágicos, pero en los oídos de la niña suena como un elegante poema."
  },
  Skill_4694_BattleDesc_0 = {
