  },
  Skill_4694_Desc_0 = {
    Text = "Gana [Counterattack:Arg2] capas de <RetaliateIconKeywords:counter>. <TouquKeywords:steal> [Arg1] <PowerIconKeywords:str> de todos los enemigos y elimina su estado de <RetaliateIconKeywords:counter>."
