  },
  Skill_4701_Desc_0 = {
    Text = "Murphy obtiene <Energy:[Energy:Arg1]> puntos de locura. <ExaltIconKeywords:despertar>: Ganas 1 tentáculo, después de que Murphy juegue una carta, obtienes 1 tentáculo temporal que ignora el límite de tentáculos, y una regeneración de llave plateada equivalente a 1 coste de aritmética, activándose un máximo de 3 veces por turno."
  },
  Skill_4701_Desc_15 = {
