  Skill_4729_AwakerSkillBackgroundStory = {
    Text = "\"Sí, así se lo prometí.\"\n Al mencionar el día de la caída de la patria, la expresión del joven rey se volvió aún más cansada. \n\"Solo espero que esas palabras alivien su miedo antes de morir, nunca pensé que lo convertiría en un estándar...\""
  },
  Skill_4729_Desc_0 = {
    Text = "Disipa su propio estado <WeaknessIconKeywords:Síntoma: Debilidad>. Obtén [TentaclePower:Arg1] puntos temporales de <TentacleInjurieIconKeywords:Daño de tentáculos> y [Power:Arg1] puntos temporales de <PowerIconKeywords:fuerza>. Si la postura actual es \"Mar tranquilo\", reduce adicionalmente [Exhaustion:Arg3] puntos de <ExhaustionIconKeywords:fuerza> a todos los enemigos en este turno. <RippleKeywords:Réplica>: impulsa 1 ataque de tentáculo contra los enemigos."
  },
  Skill_4729_Desc_3 = {
    Text = "Disipa su propio estado <WeaknessIconKeywords:Síntoma: Debilidad>. Obtén [TentaclePower:Arg1] puntos temporales de <TentacleInjurieIconKeywords:Daño de tentáculos> y [Power:Arg1] puntos temporales de <PowerIconKeywords:fuerza>. Obtén [Arg2]% de Tasa de Crítico Temporal. Si la postura actual es \"Mar tranquilo\", reduce adicionalmente [Exhaustion:Arg3] puntos de <ExhaustionIconKeywords:fuerza> a todos los enemigos en este turno. <RippleKeywords:Réplica>: impulsa 1 ataque de tentáculo contra los enemigos."
