  Skill_4745_AwakerSkillBackgroundStory = {
    Text = "Dos voluntades luchan y se enfrentan dentro de un cuerpo mecánico: una desea la destrucción, la otra no quiere someterse. Pero un pequeño humano no puede ganar por mucho tiempo, al final será devorada por la otra parte, convirtiéndose en un recipiente loco que existe solo para destruir. \n Entonces liberó toda su corriente. Un enorme arco eléctrico la envolvió, el cuerpo en cortocircuito resonó con el estallido de la electricidad, lanzó la energía acumulada hacia adelante y luego cayó en una breve incapacidad. \n \"No puedo moverme, no puedo destruir.\""
  },
  Skill_4745_Desc_0 = {
    Text = "Erica obtiene [Arg4]% de Tasa de Crítico Temporal y Daño Crítico. Obtén <Block:[Block:Arg2]> puntos de escudo. Causa <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos y aplica [Arg3] capas de <WeaknessIconKeywords:Síntoma: Debilidad> y <VulnerabilityIconKeywords:Vulnerable>."
  },
  Skill_4745_Desc_2 = {
