  Skill_4750_AwakerSkillBackgroundStory = {
    Text = "Gestar, nacer, reproducir. \n En una realidad que se disuelve cada vez más, en un mundo que se adentra en la penumbra, en un vacío que está a punto de renacer. \n Su existencia es el fruto del sacrificio de la madre, es la causa de la continuidad de la madre. \n Oh, Vástago de la Pureza, renace en el nuevo mundo—en ese nuevo mundo inmaculado, que ha disipado todo miedo."
  },
  Skill_4750_Desc_0 = {
    Text = "Thais obtiene <Energy:[Energy:Arg1]> puntos de aliemus. <ExaltIconKeywords:despertar>: obten 1 carta <DerivativeCardKeywords_10:Hijo Sagrado> inmediatamente. Cada vez que liberes una pandilla, convierte un embrión en <DerivativeCardKeywords_10:Hijo Sagrado>"
  },
  Skill_4750_Desc_15 = {
    Text = "Thais obtiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Activar>: Obtén inmediatamente 1 <DerivativeCardKeywords_10:Vástago de la Pureza>. Cada vez que se libere un Posse, transforma 1 Embrión en la mano en 1 <DerivativeCardKeywords_10:Vástago de la Pureza>. \"Ritual de la Abundancia\" coloca adicionalmente 1 copia extra en tu mano."
  },
