  Skill_4751_AwakerSkillBackgroundStory = {
    Text = "No parpadees, observa detenidamente, el momento mágico ha llegado; \nGuantes blancos, bombín negro, cartas multicolores las creo de la nada. \nTan espléndido como cintas, tan brillante como lentejuelas, \nEsta actuación deslumbrante y loca, ¡te aseguro que no puedes adivinar!"
  },
  Skill_4751_Desc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos, roba [Arg2] cartas; por cada carta de comando de casiah robada, causa <Damage:[Damage:Arg1]> puntos de daño a un enemigo aleatorio. Aumenta el daño base de todas las cartas de casiah en [Arg3]%"
  },
  Skill_4751_Desc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos, roba [Arg2] cartas, infligiendo <Damage:[Damage:Arg1]> puntos de daño a un enemigo aleatorio por cada carta de síntoma, carta de estado o carta de comando de casiah que robes. Aumenta todo el daño base de casiah en [Arg3]%"
  },
