  Skill_4751_OverLimitUtlSkillDesc_0 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de Daño a todos los enemigos [Arg4] veces, roba [Arg2] cartas, por cada Tarjeta de comando de Casiah robada causa <Damage:[Damage:Arg1]> puntos de Daño a un enemigo aleatorio [Arg4] veces. Aumenta todo el Daño básico de Casiah en [Arg3]%. Después de jugar [Arg6] Tarjetas de comando de Casiah, obtén [Power:Arg5] puntos de Fortaleza."
  },
  Skill_4751_OverLimitUtlSkillDesc_2 = {
    Text = "Causa <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos [Arg4] veces, roba [Arg2] cartas; por cada carta de síntomas, carta de estado o carta de comando de Casiah robada, causa <Damage:[Damage:Arg1]> puntos de daño a un enemigo aleatorio [Arg4] veces. Aumenta todo el daño base de Casiah en [Arg3]%. Después de jugar [Arg6] veces la carta de comando de Casiah, obtén [Power:Arg5] puntos de fuerza."
