  Skill_4769_tempBattleDesc_1 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo y [Counterattack:Arg2] capas <RetaliateIconKeywords:contrataque>, el próximo efecto de impulso de este turno se activará sin falta. Puedes elegir consumir capas de <DreamGuide:Onirismo> para activar <JingjinvwangKeywords1:Contador de sueño> o <JingjinvwangKeywords2:Ecos de susurros>. Si las capas de <DreamGuide:Onirismo> son insuficientes (menos de 5 capas), obtienes 1 capa de <DreamGuide:Onirismo>."
  },
  Skill_4769_tempBattleDesc_2 = {
    Text = "Obtiene <Block:[Block:Arg1]> puntos de escudo y [Counterattack:Arg2] capas de <RetaliateIconKeywords:Contraataque>. El siguiente efecto de Salto de este turno se activa con certeza. Sin consumir Guía Onírica, activa simultáneamente \"<JingjinvwangKeywords3:Pulso Hipnótico>\",\"<JingjinvwangKeywords1:Contraataque de Sueño Profundo>\" y \"<JingjinvwangKeywords2:Eco de Delirio>\". Las siguientes 2 cartas de comando jugadas por Wanda surten efecto 1 vez adicional."
