  Skill_4804_AwakerSkillBackgroundStory = {
    Text = "Las llamas se propagan, iluminando el cúpula del teatro con un color esmeralda, como el agua clara y tranquila de un lago en la mañana.\nCuántas personas han venido persiguiendo esa figura de color esmeralda, y cuántas han ignorado esa danza fluida y llena de fuerza, solo viendo los brazos de jade que asoman y la fantasía de lo que hay debajo de la falda.\nY el bailarín simplemente permanece allí, como congelado, con una postura moribunda consumida por las llamas verdes."
  },
  Skill_4804_Desc_0 = {
    Text = "Liz obtiene <Energy:[Energy:Arg1]> puntos de locura. <ExaltIconKeywords:Despertar de la sabiduría>: Cada [Arg2] veces que Liz cause daño, añade una carta <DepleteIconKeywords:consumir> <DerivativeCardKeywords_18:\"Llama Verde\"> a su mano, máximo 3 veces por turno"
