  Skill_4822_AwakerSkillBackgroundStory = {
    Text = "En la interminable vagancia, Tinct ya ha olvidado el nombre de su hogar.\nEn los largos años, el universo ha olvidado el nombre de ese planeta muerto.\nÉl, al igual que muchos planetas disueltos y abandonados, se conoce como \"Estrella Desolada\".\nSu canto, tal vez, sea la última resonancia de ese planeta exterior."
  },
  Skill_4822_Desc_0 = {
    Text = "Tinctura obtiene <Energy:[Energy:Arg1]> puntos de aliemus, <ExaltIconKeywords:despertar> : Aumenta el daño base de\"golpe\"de Tinctura en [Arg2]%, todas las cartas de Tinctura obtienen 1 efecto aleatorio, que se eliminará al final de la batalla"
  },
  Skill_4822_Desc_15 = {
    Text = "Tinct obtiene <Energy:[Energy:Arg1]> de Aliemus, <ExaltIconKeywords:Despertar>: El Daño básico de \"golpear\" de Tinct +[Arg2]%, todas las Cartas de Tinct obtienen 1 efecto aleatorio, que se eliminará al final de la batalla. La primera vez que Tinct Juegue una \"Habilidad\" cada turno, genera 1 \"golpear\" Temporal con 0 de Coste de Aritmética, los efectos aleatorios de este \"golpear\" x2."
  },
