  Skill_59477_AwakerSkillBackgroundStory = {
    Text = "¿De dónde nace la música? De rituales que agradan a los dioses, de los cantos de los campesinos, de los aullidos de los primitivos, del canto de los mirlos en primavera, del viento entre los pinos y las olas del mar, de las vibraciones de la tierra y del colapso de las montañas... o tal vez de los murmullos en el sueño de los dioses en medio del caos."
  },
  Skill_59477_BattleDesc_0 = {
    Text = "Causa aleatoriamente <Damage:[Damage:Arg1]> puntos de <PunctureDamagewords:Daño Penetrante> [Arg3] veces, por cada daño infligido reduce temporalmente [Exhaustion:Arg2] puntos de <ExhaustionIconKeywords:fuerza> del objetivo y obtiene [Power:Arg2] puntos de <PowerIconKeywords:STR temporal>. Elige 1 tarjeta de comando en tu mano que no tenga \"Melodía\", que sea no consumible y no derivada, para añadir \"<HuihuanaKeywords:Rondino>\". Cada vez que no haya cartas en la mano que puedan ser añadidas, inflige 3 puntos de daño adicionales."
  },
  Skill_59477_BattleDesc_2 = {
    Text = "Causa aleatoriamente <Damage:[Damage:Arg1]> puntos de<PunctureDamagewords:Daño Penetrante> [Arg3] veces, por cada daño infligido reduce temporalmente [Exhaustion:Arg2] puntos de <ExhaustionIconKeywords:fuerza> del objetivo y obtiene [Power:Arg2] puntos de <PowerIconKeywords:STR temporal>. Elige 1 carta de comando no consumible y no derivada en tu mano que no tenga\"Melodía\"para añadir\"<HuihuanbKeywords:Rondino>». Si no hay cartas en la mano que puedan ser añadidas, inflige 3 puntos de daño adicionales."
  },
  Skill_59477_Desc_0 = {
    Text = "Causa aleatoriamente <Damage:[Damage:Arg1]> puntos de <PunctureDamagewords:daño de perforación> 3 veces, y por cada daño infligido <TouquKeywords:robar> [Arg2] puntos de <PowerIconKeywords:fuerza>. Elige 1 tarjeta de comando en tu mano que no tenga \"Melodía\" y que sea no consumible y no derivada para agregar \" <HuihuanaKeywords:Rondino>\". Si no hay cartas en la mano que puedan ser agregadas, inflige en su lugar 3 puntos de daño adicionales."
  },
  Skill_59477_Desc_2 = {
    Text = "Causa aleatoriamente <Damage:[Damage:Arg1]> puntos de <PunctureDamagewords:daño de perforación> 3 veces, y por cada daño infligido <TouquKeywords:robar> al objetivo [Arg2] puntos de <PowerIconKeywords:fuerza>. Selecciona 1 tarjeta de comando en mano que no tenga \"Melodía\", que sea no consumible y no derivada para añadir \" <HuihuanbKeywords:Rondino>\". Si no hay cartas en mano que puedan ser añadidas, inflige en su lugar 3 puntos de daño adicionales."
  },
