  Skill_61123_AwakerSkillBackgroundStory = {
    Text = "¡Canta, diosa! Canta el destino de la hija de Delos:\nLleno de sangre y lágrimas, rabia y desesperación.\nSu odio ardía como fuego, consumiendo todo a su alrededor, pero al final,\nTrajo su propia muerte"
  },
  Skill_61123_Desc_0 = {
    Text = "Helot: Catena obtiene <Energy:[Energy:Arg1]> puntos de alienación. <ExaltIconKeywords:Activar>: Coloca una carta de \"<DerivativeCardKeywords_65:Grilletes carmesí>\" en tu mano, y la carta de comando de Helot: Catena obtiene \"<RetainIconKeywords:Retener>». Al comienzo del turno, el daño básico de Helot: Catena aumenta en [Arg2]% en esta batalla."
  },
  Skill_61123_Desc_15 = {
    Text = "Helot: Catena obtiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Despertar>: Coloca unos \"<DerivativeCardKeywords_65:Grilletes carmesí>\" en la mano, y las Tarjetas de comando de Helot: Catena obtienen \"<RetainIconKeywords:Retener>\". Al inicio del turno, el Daño básico de Helot: Catena +[Arg2]% para esta batalla. Después de desatar Exaltar \"Grilletes sanguíneos,\" otorga a cada Tarjeta de comando única de \"Helot: Catena\" en mano 35 Acumulaciones de <TempPowerKeywords:Mejorar Temporal>."
  },
