  Skill_70303_AwakerSkillBackgroundStory = {
    Text = "Si la humanidad ya camina por el camino de aniquilación de una sola dirección, ¿sería una misericordia darle un pequeño empujón?\nQue el apocalipsis suceda en un instante. Que el dolor se cristalice. Que los amantes se abracen mientras el olvido los lleva.\nSi al final ya no hay dolor, ¿podría eso, por fin, ser el paraíso?"
  },
  Skill_70303_BattleDesc_0 = {
