  Skill_78785_AwakerSkillBackgroundStory = {
    Text = "\"Por favor, dime, ¿quién eres realmente?\"\n Así preguntó, y ella se rió. \n El pobre paciente, por supuesto, no pudo responder, ya que su memoria había sido alterada; cuanto más buscaba, más se acercaba a la aterradora existencia implantada en su memoria—hasta que su cognición colapsara por completo y se convirtiera en un monstruo."
  },
  Skill_78785_BattleDesc_0 = {
    Text = "Elimina toda tu <AnalysisKeywords0:Empatía> y elige transformarla en <D13AFKeyWord2:Trauma psicológico> o <D13AFKeyWord1:Fijación fóbica> para todos los enemigos [Arg6] veces. Inflige <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos y obtén <Posse:[Arg3]> puntos de Keyflare."
  },
  Skill_78785_BattleDesc_2 = {
    Text = "Elimina toda tu <AnalysisKeywords0:Empatía> y elige transformarla en <D13AFKeyWord2:Trauma psicológico> o <D13AFKeyWord1:Fijación fóbica> para todos los enemigos. Por cada capa eliminada, el Daño básico causado por Clementine aumenta en un 3%. Inflige <Damage:[Damage:Arg1]> puntos de daño a todos los enemigos [Arg6] veces y obtén <Posse:[Arg3]> puntos de Keyflare."
  },
  Skill_78785_BattleDesc_3 = {
