  Skill_83574_BattleDesc = {
    Text = "Elimina todas las acumulaciones de \"Levanta velas\" ([Arg1]). Por cada acumulación eliminada, Daño Final +[Arg2]%, y todos los Despertados ganan [Arg3] de Alienación.\nSi se eliminan 5 o más acumulaciones de \"Levanta velas\" a la vez, aplica <VulnerabilityIconKeywords:Vulnerable> a todos los enemigos durante 1 turno, infligiéndoles <RealDamage:Daño Fijo> igual al [Arg4]% de sus Puntos de vida perdidos."
  },
  Skill_83574_Desc = {
    Text = "Elimina todas las acumulaciones de \"Levanta velas\". Por cada acumulación eliminada, Daño Final +10%, y todos los Despertados ganan 5 de Alienación.\nSi se eliminan 5 o más acumulaciones de \"Levanta velas\" a la vez, inflige \"Vulnerable\" a todos los enemigos durante 1 turno, causando <RealDamage:Daño Fijo> igual al 35% de sus Puntos de vida perdidos."
  },
  Skill_83574_Name = {Text = "Archor Off"},
  Skill_83575_BattleDesc = {
    Text = "Elimina todas las capas de \"Echar el ancla\"([Arg1]). Por cada capa eliminada, la resistencia a la muerte aumenta en [Arg2]%, obtén [Arg3] puntos de aritmética y roba [Arg4] cartas. \nSi eliminas 5 o más capas de \"Echar el ancla\" de una vez, obtén [Arg5] capas temporales de <ParcloseIconKeywords:barrera>."
  },
  Skill_83575_Desc = {
    Text = "Elimina todas las capas de \"Ancla fondeada\". Por cada capa eliminada, aumenta la \"resistencia a la muerte\" en 15%, obtén 1 punto de aritmética y roba 1 carta. \nSi eliminas 5 o más capas de \"Ancla fondeada\" de una vez, obtén 1 capa de \"barrera\"."
  },
  Skill_83575_Name = {
    Text = "Descanso albergado"
  },
  Skill_83576_BattleDesc = {
    Text = "Selecciona: «Navegar entre olas» ([Arg1]) o «Descansar en la orilla» ([Arg2]). Al descartarla, la <DepleteIconKeywords:consumes>."
  },
  Skill_83576_Desc = {
    Text = "Selecciona: «Navegar entre olas» o «Descansar en la orilla». Al descartarla, la <DepleteIconKeywords:consumes>."
  },
  Skill_83576_Name = {
    Text = "El dilema del navegante"
  },
  Skill_83779_AwakerSkillBackgroundStory = {
    Text = "Las infinitas aguas saladas devoraron a ella, al mismo tiempo que la protegieron. \n En esa asfixiante sensación de hundimiento, ella percibía el océano profundo, integrándose en el océano profundo. \n Un día, el océano estará completamente en calma, cada barco que navegue sobre la superficie del mar será bendecido con paz. \n Ella espera ese día, el \"día de la llegada del Reino Divino\"."
  },
  Skill_83779_Desc_0 = {
    Text = "Corposant obtiene <Energy:[Energy:Arg1]> puntos de alienación. <ExaltIconKeywords:Activar>: gana 1 tentáculo, coloca 2 cartas de \"<DerivativeCardKeywords_106:Pilotar>\" en tu mano. Al cambiar a la postura de \"Mar tranquilo\", obtén <Block:[Block:Arg2]> puntos de blindaje, con un enfriamiento de 3 turnos."
  },
  Skill_83779_Desc_15 = {
    Text = "Corposant obtiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Activar>: Obtiene 1 Tentáculo, añade 2 \"<DerivativeCardKeywords_106:Piloto>\" a la mano. Para la primera \"Retribución del rayo\" y \"Semáforo siniestro\" que Corposant juega en cada turno, coloca 1 \"Piloto\" adicional en la mano. Efecto de \"<DerivativeCardKeywords_106:Piloto>\" +50%. Tras cambiar a la postura \"Mar tranquilo\", obtiene <Block:[Block:Arg2]> Escudo del personaje, con un enfriamiento de 3 turnos."
  },
  Skill_83779_EffectNameList = {
    Text = "Locura, escudo"
  },
  Skill_83779_Name = {
    Text = "Hundimiento Distante"
  },
  Skill_83779_PropertyNameList = {
    Text = "$GrowValue1, defensa*GrowValue2"
  },
  Skill_83780_AwakerSkillBackgroundStory = {
    Text = "Las nubes pueden informar sobre los cambios climáticos, las olas pueden contar la transformación de las corrientes oceánicas, pero cuando la tormenta realmente llega, incluso el más grande de los buques solo puede flotar impotente con la corriente. \n En ese momento, los cálculos y las indicaciones del piloto son el último recurso de todos los sobrevivientes. \n Así que cumple con tus responsabilidades, aunque los rayos caigan sobre ti, debes brillar con un rayo de luz en medio del dolor, guiando hacia la costa. \n Esa es la misión que debes completar."
  },
  Skill_83780_BattleDesc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo y [Arg2] tentáculos temporales. Descarta todas las cartas de tu mano y roba la misma cantidad de cartas."
  },
  Skill_83780_BattleDesc_3 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo y [Arg2] tentáculos temporales. <VulnerabilityIconKeywords:vulnerable> a todos los enemigos durante 1 ronda. Daño crítico temporal +[Arg5]%. Descarta todas las cartas de tu mano y roba una cantidad igual."
  },
  Skill_83780_Desc_0 = {
