  Skill_89750_Name = {Text = "La Vigilia"},
  Skill_89776_AwakerSkillBackgroundStory = {
    Text = "\"¿Hermano, dices que volar con alas, volar y volar, ¿hasta dónde se puede llegar? ¿Podremos llegar a las nubes y tocar la luna y las estrellas?\"\n\"Quizás... ¿podría ser? Pero necesitamos un par de alas grandes y fuertes.\"\nLas profundas y oníricas galaxias y constelaciones del manuscrito se reflejan en los sueños de los dos niños, convirtiéndose en una semilla de deseo, enterrada en sus corazones."
  },
  Skill_89776_Desc_0 = {
    Text = "Castor obtiene <Energy:[Energy:Arg1]> puntos de alienación. <ExaltIconKeywords:Despertar>: El daño causado por Castor será un golpe crítico, y tras jugar la carta \"<DerivativeCardKeywords_107:Pluma negra>\", aplica [Corrosion:Arg2] capas de <Corrosion:Corrosión> al objetivo, y el escudo retenido aumenta en un 50%."
  },
  Skill_89776_Desc_15 = {
    Text = "Castor obtiene <Energy:[Energy:Arg1]> Aliemus. <ExaltIconKeywords:Despertar>: El Daño de Castor siempre es golpe crítico; después de jugar \"<DerivativeCardKeywords_107:Pluma negra>\", inflige [Corrosion:Arg2] capas de <Corrosion:Corrosión> al objetivo. Obtiene +50% de Escudo del personaje al mantener cartas de Pluma negra en mano al final del turno. La primera vez que se juega \"Pluma negra\" en cada turno, inflige Corrosión igual al Talento \"Plumas Santificadas de Purificación\" a todos los enemigos, y los PV perdidos cuando se elimina la Corrosión aumentan del 300% al 500%."
  },
