  Skill_89778_AwakerSkillBackgroundStory = {
    Text = "Él es torpe, terco y nunca ha cambiado. Aunque solo pueda emitir un solitario graznido, no se rendirá ante ninguna cadena ni hoja afilada. Usará su pico afilado, que nunca se ha desgastado, para picotear cada grieta de la jaula. Cuando las alas negras atraviesen el borde de la noche, llevará consigo aquella última pluma, junto con su sombra, volando hacia la luz del día al otro lado de la tormenta."
  },
  Skill_89778_Desc = {
