  Skill_89781_AwakerSkillBackgroundStory = {
    Text = "Sus alas se despliegan como un amplio escudo, cada pluma conectada a un esqueleto resistente, temblando suavemente sobre tu cabeza.\n Esa sombra negra te envuelve, ocultando toda la luz del sol, la lluvia y el daño, sosteniendo un cielo seguro.\n \"No lo toques, deja que estas maldiciones oscuras regresen por completo al pecho del agresor.\""
  },
  Skill_89781_Desc_0 = {
    Text = "Obtén <Block:[Block:Arg1]> puntos de escudo. Aplica <WeaknessIconKeywords:debilidad> a todos los enemigos durante 1 ronda. <WormholeKeywords:Telequinesis>: Baraja 1 carta \"<DerivativeCardKeywords_107:Pluma Negra>\" en la pila de robo y obtén <Block:[Block:Arg3]> puntos de escudo."
