  Skill_89782_AwakerSkillBackgroundStory = {
    Text = "Él no es de los que soportan, esas alas también pueden levantar un vórtice de furia. \n Toda carne y sangre será desgarrada por los afilados dientes del viento, arrastrándose con violencia hacia el vientre de la muerte. \n Pero no debes temer, él colocará tu nombre en el ojo del huracán, en la calma más central."
  },
  Skill_89782_Desc_0 = {
    Text = "Inflige <Damage:[Damage:Arg1]> puntos de daño [Arg2] veces, aumentando en [Arg3]% el daño crítico temporal de los demás aliados. <WormholeKeywords:Telequinesis>: Baraja 1 carta \"<DerivativeCardKeywords_107:Pluma Negra>\" en la pila de robo y obtén <Block:[Block:Arg4]> puntos de escudo."
  },
  Skill_89782_Desc_2 = {
