  Skill_95818_Name = {
    Text = "Exceso de pandemonio"
  },
  Skill_95819_BattleDesc = {
    Text = "Elimina todas las capas de \"Saciedad\", descarta todas las cartas en tu mano. Coloca en tu mano las cartas eliminadas a través de <DerivativeCardKeywords_111:\"Devorar Almas\">, estableciendo su Coste de Aritmética en 0. Al final del turno, si tienes en tu mano: coloca aleatoriamente una copia de una carta eliminada en tu mano, estableciendo su Coste de Aritmética en 0, y obtén consumo y Oblivion."
  },
  Skill_95819_Desc = {
    Text = "Elimina todas las capas de \"Saciedad\", descarta todas las cartas en tu mano. Coloca en tu mano las cartas eliminadas a través de <DerivativeCardKeywords_111:\"Devorar Almas\">, estableciendo su Coste de Aritmética en 0. Al final del turno, si tienes en tu mano: coloca aleatoriamente una copia de una carta eliminada en tu mano, estableciendo su Coste de Aritmética en 0, y obtén consumo y Oblivion."
  },
  Skill_95819_Name = {
    Text = "Resonancia de Memoria"
  },
  Skill_95820_AwakerSkillBackgroundStory = {
    Text = "Desgarra tu disfraz. Deja de lado tus prejuicios. Entra en la pista de baile y abraza a tu compañero de danza que ha estado dormido durante años. \n ¿Cuánto tiempo ha pasado desde que vio la hermosa luz de la luna? ¿Cuánto tiempo ha pasado desde que escuchó dulces palabras de amor? \n Escucha, está deseándote, así como tú lo anhelas a él. \n Muerde, devora. En este banquete incomparable, los seres vivos y los muertos completan su sublimación conjunta."
  },
  Skill_95820_BattleDesc_0 = {
    Text = "[<DevouredIconKeywords:Devorar> :<DerivativeCardKeywords_110:>La tasa de crítico de esta explosión de locura +[Arg2]%, gana [Power:Arg1] puntos de <PowerIconKeywords:fuerza>.]Causa <Damage:[Damage:Arg3]> puntos de daño al enemigo con menos vida, disfrutando de un bono de fuerza del [Arg4]%. Por cada 1% de vida que pierda el objetivo, el daño final de esta explosión de locura aumenta en un 3%. Si actualmente posees 3 <CarcassKeywords:Cadáveres>, los consumes, recuperas <Heal:[Heal:Arg5]> puntos de vida y duplicas el bono de daño crítico disfrutado por esta explosión de locura (actualmente posees [Arg6]/3 <CarcassKeywords:cadáveres>)."
  },
  Skill_95820_BattleDesc_3 = {
    Text = "[<DevouredIconKeywords:Devorar> :<DerivativeCardKeywords_114:>Esta explosión de locura aumenta la probabilidad de crítico en +[Arg2]%, y obtiene [Power:Arg1] puntos de <PowerIconKeywords:poder>.]Causa <Damage:[Damage:Arg3]> puntos de daño al enemigo con menos vida, disfruta de una bonificación de fuerza del [Arg4]%, y el daño final de esta explosión de locura aumenta en un 3% por cada 1% de vida que el objetivo pierde. Si actualmente tienes 3 <CarcassKeywords:Cadáveres>, consumelos, recupera <Heal:[Heal:Arg5]> puntos de vida y duplica la bonificación de daño crítico de esta explosión de locura (actualmente tienes [Arg6]/3 <CarcassKeywords:cadáveres>)."
  },
  Skill_95820_Desc_0 = {
    Text = "[<DevouredIconKeywords:Devorar> :<DerivativeCardKeywords_110:> La tasa de golpe crítico de esta exaltación de locura +[Arg2]%, gana [Power:Arg1] puntos de <PowerIconKeywords:fuerza>.]Causa <Damage:[Damage:Arg3]> puntos de daño al enemigo con la vida más baja, disfrutando de una bonificación de fuerza del [Arg4]%. Por cada 1% de vida que pierda el objetivo, el daño final de esta exaltación de locura aumenta en un 3%. Si actualmente tienes 3 <CarcassKeywords:Cadáveres>, consúmelos, recupera <Heal:[Heal:Arg5]> puntos de vida y duplica la bonificación de daño crítico disfrutada por esta exaltación de locura."
  },
  Skill_95820_Desc_3 = {
    Text = "[<DevouredIconKeywords:Devorar> :<DerivativeCardKeywords_114:> La tasa crítica de esta exaltación de locura aumenta en [Arg2]%, y obtiene [Power:Arg1] puntos de <PowerIconKeywords:fuerza>.]Causa <Damage:[Damage:Arg3]> puntos de daño al enemigo con menos vida, disfrutando de un aumento de fuerza del [Arg4]%. Por cada 1% de vida que el objetivo pierda, el daño final de esta exaltación de locura aumenta en un 3%. Si actualmente tienes 3 <CarcassKeywords:Cadáveres>, consúmelos para recuperar <Heal:[Heal:Arg5]> puntos de vida y duplicar la bonificación de daño crítico disfrutada por esta exaltación de locura."
  },
  Skill_95820_EffectNameList = {
    Text = "Poder, Daño, Curar"
